INSERT INTO `pt_api` VALUES (2001, '执行插件工具', '执行插件工具', '执行插件工具接口\r\n\r\n## 接口鉴权\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n    * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n    * 示例: `Authorization: Bearer xxx`\r\n\r\n## 接口地址\r\n* 请求方法: POST\r\n* 请求地址: `/plugin/manager/plugin/execute`\r\n\r\n## 接口入参\r\n```json\r\n{\r\n  \"pluginId\": \"1320584359766908928\",\r\n  \"toolName\": \"aesEncrypt\",\r\n  \"toolParams\": {\r\n    \"auth\": {\r\n      \"Authorization\": \"123456\"\r\n    },\r\n    \"body\": {\r\n      \"text\": \"123456\",\r\n      \"aesKey\": \"Aa#123\"\r\n    }\r\n  }\r\n}\r\n```\r\n\r\n## 接口出参\r\n```json\r\n{\r\n  \"resultCode\": \"0\",\r\n  \"resultMsg\": \"success\",\r\n  \"resultObject\": {\r\n    \"encryptText\": \"luZN7EpFQ0qC43H8PPswTg==\"\r\n  }\r\n}\r\n```', '/plugin/manager/plugin/execute', 'POST', '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"parentKeyPath\":[],\"children\":[{\"description\":\"鉴权\",\"name\":\"Authorization\",\"type\":\"string\",\"require\":true,\"value\":\"\",\"key\":\"37fab773-11e4-4286-b1f2-8f056d171447\",\"parentKey\":-1,\"parentKeyPath\":[-1]}]}', NULL, NULL, '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"parentKeyPath\":[],\"children\":[{\"description\":\"插件ID\",\"name\":\"pluginId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"61e151f4-6fef-4ce6-9158-96eb989cc18c\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"工具名称\",\"name\":\"toolName\",\"type\":\"string\",\"require\":true,\"value\":\"\",\"key\":\"a30fb79d-4c74-4029-b22d-72c1f85b77b3\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"工具参数\",\"name\":\"toolParams\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"a30fb79d-4c74-4029-b22d-72c1f85b77b4\",\"parentKey\":-1,\"parentKeyPath\":[-1]}]}', '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"va