:\"d2682bd2-eb34-44aa-ac3e-8a0dd91aa428\",\"parentKey\":\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\",\"parentKeyPath\":[-1,\"4bf79671-c545-420c-a48f-904e7551ffdf\",\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\"]},{\"description\":\"订阅状态\",\"name\":\"subscribeStatus\",\"type\":\"boolean\",\"require\":false,\"value\":\"\",\"key\":\"ecb4ce46-99ac-47dd-952b-feeeb5be1d93\",\"parentKey\":\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\",\"parentKeyPath\":[-1,\"4bf79671-c545-420c-a48f-904e7551ffdf\",\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\"]},{\"description\":\"插件类型\",\"name\":\"pluginType\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"72300fa8-69bf-433a-b864-d6ba85a6a173\",\"parentKey\":\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\",\"parentKeyPath\":[-1,\"4bf79671-c545-420c-a48f-904e7551ffdf\",\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\"]},{\"description\":\"插件子分类\",\"name\":\"pluginSubType\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"62ea2815-163e-4904-be9a-83332d93d644\",\"parentKey\":\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\",\"parentKeyPath\":[-1,\"4bf79671-c545-420c-a48f-904e7551ffdf\",\"b9faddbe-0f5c-49bf-add7-2c9848e3d1ce\"]}]}]}]}', NULL, 202601201, NULL, '00A', NULL, 1, NULL, NULL), (3004, '查询插件定义', '查询插件定义', '查询插件定义接口\r\n\r\n## 接口鉴权\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n  * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n  * 示例: `Authorization: Bearer xxx`\r\n\r\n## 接口地址\r\n* 请求方法: POST\r\n* 请求地址: `/plugin/manager/plugin/getPluginDefinition`\r\n\r\n## 接口入参\r\n```json\r\n{\r\n  \"pluginId\": 1,\r\n  \"includeTools\": true\r\n}\r\n```\r\n\r\n## 接口出参\r\n```json\r\n{\r\n  \"resultCode\": \"0\",\r\n  \"resultMsg\": \"success\",\r\n  \"resultObject\": {\r\n    \"pluginId\": \"1\",\r\n    \"pluginName\": \"证件识别\",\r\n    \"pluginCode\": \"plugin_1320683444419289088\",\r\n    \"remark\": \"提供各类证件的OCR识别与信息提取功能，包括身份证、银行卡、护照等。\",\r\n    \"pluginIntro\": \"## 插件描述\\n  提供各类证件的OCR识别与信息提取功能，包括身份证、银行卡、护照等。\\n\\n  ## 使用场景\\n  - **身份证识别**：用于身份验证、实名认证等场景\\n  - **银行卡识别**：用于快速录入银行卡信息、在线支付等场景\\n  - **护照识别**：用于出入境管理、签证申请等场景\\n  - **营业执照识别**：用于企业信息录入、工商审核等场景\\n  - **学位证书识别**：用于学历验证、教育背景核实等场景\\n  - **驾驶证识别**：用于驾驶员信息管理、交通管理等场景\\n  - **户口本识别**：用于户籍管理、人口统计等场景\\n  - **组织机构代码证识别**：用于机构信息验证、企业资质审核等场景\\n\\n  ## 参数说明\\n  - **file**（图片文件）：\\n    - 类型：file\\n    - 说明：需要识别的证件图片文件\\n    - 必填：否（与base64二选一）\\n\\n  - **base64**（图片base64）：\\n    - 类型：string\\n    - 说明：需要识别的证件图片的base64编码\\n    - 必填：否（与file二选一）\",\r\n    \"catalogItemId\": \"1320646951717392384\",\r\n    \"pluginType\": \"tool\",\r\n    \"pluginSubType\": \"local\",\r\n    \"relativePath\": \"/plugin/certificateIdentify/execute\",\r\n    \"gatewayId\": \"1320583828336009216\",\r\n    \"configOnUse\": false,\r\n    \"subscribeStatus\": true,\r\n    \"discoveryToolType\": \"sdk\",\r\n    \"discoveryToolPath\": \"/plugin/certificateIdentify/detail\",\r\n    \"gateway\": {\r\n      \"gatewayId\": \"1320583828336009216\",\r\n      \"gatewayName\": \"博特官方 Java 插件集\",\r\n      \"gatewayType\": \"http\",\r\n      \"url\": \"http://10.10.202.25:9080/java/\",\r\n      \"userName\": null,\r\n      \"password\": \"\",\r\n      \"apiKey\": null,\r\n      \"higressRuntimeUrl\": null\r\n    }\r\n  }\r\n}\r\n```', '/plugin/manager/plugin/getPluginDefinition', 'POST', '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"parentKeyPath\":[],\"children\":[{\"description\":\"鉴权\",\"name\":\"Authorization\",\"type\":\"string\",\"require\":true,\"value\":\"\",\"key\":\"127008e8-d93e-4f57-9c97-5c61c9b36fd8\",\"parentKey\":-1,\"parentKeyPath\":[-1]}]}', NULL, NULL, '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"parentKeyPath\":[],\"children\":[{\"description\":\"插件ID\",\"name\":\"pluginId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"61e151f4-6fef-4ce6-9158-96eb989cc18c\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"是否包含工具\",\"name\":\"includeTools\",\"type\":\"boolean\",\"require\":true,\"value\":\"\",\"key\":\"a30fb79d-4c74-4029-b22d-72c1f85b77b3\",\"parentKey\":-1,\"parentKeyPath\":[-1]}]}', '{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"parentKeyPath\":[],\"children\":[{\"description\":\"状态码，0 表示成功, 其它均为失败\",\"name\":\"resultCode\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"fa56ee32-e1a5-427d-82c4-7a416ef0e098\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"提示信息\",\"name\":\"resultMsg\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"590ec87a-bbe8-4ab5-a809-e9a77c72ff41\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"返回对象\",\"name\":\"resultObject\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKey\":-1,\"parentKeyPath\":[-1],\"children\":[{\"description\":\"插件ID\",\"name\":\"pluginId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"2d571996-fd25-46d6-a4cd-e28f92ce1467\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件名称\",\"name\":\"pluginName\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"7f5ebcb6-8466-4a23-90ae-ec1bb70f4dc5\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件编码\",\"name\":\"pluginCode\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"3329eb46-620e-4dc0-bfa0-8ba696a71b77\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件描述\",\"name\":\"remark\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"3883c686-1d9d-4486-bb20-bbdc3967e3b1\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件功能介绍\",\"name\":\"pluginIntro\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"3f78a769-54b1-4ea6-bfba-66cd48bfd37c\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"目录ID\",\"name\":\"catalogItemId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"2aa1fda5-8aee-49f0-a332-d83bd2ce5b8d\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件类型\",\"name\":\"pluginType\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"940883eb-087c-42c6-9319-8621433ea019\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"插件子分类\",\"name\":\"pluginSubType\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"b1257ea5-8ad7-41c2-8fff-3c755e2d036a\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"服务地址\",\"name\":\"relativePath\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"1a05e1f7-073c-4b7d-abfc-643bea2f6556\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"订阅时是否提醒展示认证信息\",\"name\":\"configOnUse\",\"type\":\"boolean\",\"require\":false,\"value\":\"\",\"key\":\"0d06bf63-c314-40eb-9a8e-d290ab11e7b6\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"订阅状态\",\"name\":\"subscribeStatus\",\"type\":\"boolean\",\"require\":false,\"value\":\"\",\"key\":\"11055b40-da9d-4972-925c-be162720ca58\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"自动发现工具方式\",\"name\":\"discoveryToolType\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"e79a68b8-918a-496a-a362-54dd960297b5\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"自动发现工具地址\",\"name\":\"discoveryToolPath\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"9b7b3827-216f-4e81-9aa8-43df440d0a16\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"网关\",\"name\":\"gateway\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"1ff3fc43-a48f-4ab3-b9ba-28e5764283c6\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]},{\"description\":\"工具列表\",\"name\":\"tools\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"052282df-264e-4a59-9d62-b40c6d78063d\",\"parentKey\":\"47badfd0-a4c5-4713-892b-f3d723b01d9e\",\"parentKeyPath\":[-1,\"47badfd0-a4c5-4713-892b-f3d723b01d9e\"]}]}]}', NULL, 202601201, NULL, '00A', NULL, 1, NULL, NULL), (3005, '获取插件的工具列表', '获取插件的工具列表', '获取插件的工具列表接口\r\n\r\n## 接口鉴权\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n    * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n    * 示例: `Authorization: Bearer xxx`\r\n\r\n## 接口地址\r\n* 请求方法: POST\r\n* 请求地址: `/plugin/manager/plugin/getPluginTools`\r\n\r\n## 接口入参\r\n\r\n```json\r\n{\r\n  \"pluginId\": 1\r\n}\r\n```\r\n\r\n## 接口出参\r\n\r\n```json\r\n{\r\n  \"resultCode\": \"0\",\r\n  \"resultMsg\": \"success\",\r\n  \"resultObject\": [\r\n    {\r\n      \"name\": \"idCard\",\r\n      \"title\": \"身份证识别\",\r\n      \"description\": \"识别身份证正反面信息\",\r\n      \"llmDescription\": \"识别身份证正反面信息。使用此工具识别身份证信息。参数格式必须是：`{\\\"body\\\":{\\\"file\\\":\\\"文件ID\\\"}}`。file参数的值必须从用户消息中的fileIds提取。\",\r\n      \"input\": {\r\n        \"type\": null,\r\n        \"parameters\": null,\r\n        \"header\": null,\r\n        \"path\": null,\r\n        \"query\": null,\r\n        \"body\": [\r\n          {\r\n            \"name\": \"file\",\r\n            \"description\": \"图片文件\",\r\n            \"type\": \"file\",\r\n            \"required\": true\r\n          },\r\n          {\r\n            \"name\": \"base64\",\r\n            \"description\": \"图片base64（可选）\",\r\n            \"type\": \"string\",\r\n            \"required\": false\r\n          },\r\n          {\r\n            \"name\": \"llm\",\r\n            \"description\": \"模型信息\",\r\n            \"type\": \"object\",\r\n            \"required\": true,\r\n            \"children\": [\r\n              {\r\n                \"name\": \"url\",\r\n                \"description\": \"模型地址\",\r\n                \"type\": \"string\",\r\n                \"required\": true\r\n              },\r\n              {\r\n                \"name\": \"model\",\r\n                \"description\": \"模型名称\",\r\n                \"type\": \"string\",\r\n                \"required\": true\r\n              },\r\n              {\r\n                \"name\": \"apiKey\",\r\n                \"description\": \"认证信息\",\r\n                \"type\": \"string\"\r\n              }\r\n            ],\r\n            \"format\": \"llm_model\"\r\n          }\r\n        ],\r\n        \"bodyType\": \"multipart\"\r\n      },\r\n      \"output\": {\r\n        \"type\": \"json\",\r\n        \"parameters\": [\r\n          {\r\n            \"name\": \"emblemSide\",\r\n            \"description\": \"人像面\",\r\n            \"type\": \"object\",\r\n            \"children\": [\r\n              {\r\n                \"name\": \"name\",\r\n                \"description\": \"姓名\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"sex\",\r\n                \"description\": \"性别\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"nation\",\r\n                \"description\": \"民族\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"birth\",\r\n                \"description\": \"出生年月\",\r\n                \"type\": \"date\"\r\n              },\r\n              {\r\n                \"name\": \"address\",\r\n                \"description\": \"地址\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"id\",\r\n                \"description\": \"身份证号\",\r\n                \"type\": \"string\"\r\n              }\r\n            ]\r\n          },\r\n          {\r\n            \"name\": \"portraitSide\",\r\n            \"description\": \"国徽面\",\r\n            \"type\": \"object\",\r\n            \"children\": [\r\n              {\r\n                \"name\": \"validDate\",\r\n                \"description\": \"有效期\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"effectiveDate\",\r\n                \"description\": \"有效期开始时间\",\r\n                \"type\": \"date\"\r\n              },\r\n              {\r\n                \"name\": \"expireDate\",\r\n                \"description\": \"有效期结束时间\",\r\n                \"type\": \"date\"\r\n              },\r\n              {\r\n                \"name\": \"effectiveYear\",\r\n                \"description\": \"有效期开始年份\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"effectiveMonth\",\r\n                \"description\": \"有效期开始月份\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"effectiveDay\",\r\n                \"description\": \"有效期开始日期\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"expireYear\",\r\n                \"description\": \"有效期结束年份\",\r\n                \"type\": \"string\"\r\n              },\r\n              {\r\n                \"name\": \"expireMonth\",\r\n                \"description\": \"有效期结束月份\",\r\n                \