INSERT INTO `pt_plugin` VALUES (2, '博查AI搜索', 'bochaSearch', 'data:image/png;base64,', 3000, 1320647076380495872, 'mcp', '1', 'sse', '/sse', 1, '2025-12-09 01:40:53', '00A', 1, '2026-04-17 20:30:21', '博查是一个给AI用的搜索引擎，让你的AI应用从近百亿网页和生态内容源中获取高质量的世界知识，涵盖天气、新闻、百科、医疗、火车票、图片等多种领域。', '[{\"type\":\"header\",\"name\":\"密钥\",\"code\":\"Authorization\",\"value\":\"Bearer <api-key>\"}]', '## 什么是博查 AI 搜索 MCP 服务？\r\n\r\n博查是一个给 AI 用的搜索引擎，让你的 AI 应用从近百亿网页和生态内容源中获取高质量的世界知识，涵盖天气、新闻、百科、医疗、火车票、图片等多种领域。\r\n\r\n\r\n## 博查 AI 搜索 MCP 服务的关键特性\r\n\r\n**1. Bocha Web Search**\r\n\r\n从博查搜索全网信息和网页链接，返回结果包括网页标题、网页 URL、网页摘要、网站名称、网站图标、发布时间、图片链接等。\r\n\r\n**2. Bocha AI Search**\r\n\r\n在博查网页搜索的基础上，AI 识别搜索词语义并额外返回垂直领域内容的结构化模态卡，例如天气卡、日历卡、百科卡等几十种模态卡，在语义识别、搜索结果时效性、内容丰富性等方面更好。\r\n\r\n## 博查AI搜索 MCP 服务的使用案例\r\n\r\n目前博查已经累计服务 **3000+ 企业用户**和 **20000+ 开发者用户**，并且成为 **DeepSeek 官方联网搜索供应方**以及**阿里云官方推荐的搜索 API**，目前**承接着国内 60% 以上 AI 应用的联网搜索请求**。博查的搜索内容源包括全网近百亿个网页，以及生态合作内容（含短视频、新闻、百科、天气、医疗、火车票、酒店、餐厅、景点、企业、学术等）。博查后续将会继续与各个平台在内容生态、智能体创作等方面开展共创合作，为博查用户的搜索问题提供丰富多彩的答案。\r\n\r\n## 常见问题解答\r\n\r\n**1. Bocha Web Search API 服务可以提供什么样的能力?**\r\n\r\nBocha Web Search 提供全网通用搜索能力。您可以从博查搜索全网信息和网页链接，返回结果包括网页标题、网页URL、网页摘要、网站名称、网站图标、发布时间、图片链接等，每次搜索结果返回的网页最多支持 50 条（count50）。\r\n\r\n传统搜索引擎使用的是关键字+竞价排名机制的搜索算法，搜索结果的目标不是直接为用户提供正确的答案，而是吸引用户点击以获得广告收入。\r\n\r\n博查是基于多模态混合搜索与语义排序技术的新一代搜索引擎，支持AI应用场景的自然语言搜索方式，同时搜索结果目标是提供干净、准确、高质量的答案。\r\n\r\n博查的语义排序技术基于 Transformer 架构，会根据搜索结果与用户问题的语义相关性进行排序。由于大模型同样是 Transformer 架构，通过判断上下文与用户问题的语义相关性进行取舍，因此最终大模型更加喜欢博查提供的搜索结果。\r\n\r\n目前博查的搜索效果是国内最接近 Bing Search API 的搜索引擎，由于 Bing Search API 数据会出海（无国内 Region）、价格昂贵（15 美元/千次）且不提供文本摘要（只有 50-100 字的 snippet），国内很多企业客户都已经从 Bing 切换至博查。\r\n\r\n**2. Bocha AI Search API 服务可以提供什么样的能力？**\r\n\r\nBocha AI Search 在博查 Web Search 的基础上，AI识别搜索词语义并额外返回垂直领域内容的结构化模态卡，例如天气卡、日历卡、百科卡等几十种模态卡，在语义识别、搜索结果时效性、内容丰富性等方面更好。\r\n\r\n目前支持的模态卡类型包括：天气、百科、医疗、万年历、火车、星座属相、贵金属、汇率、油价、手机、股票、汽车等。\r\n\r\n以股票信息为例，网页中一般无法获取到实时的股票数据，需要结构化模态卡来支撑。例如Google中搜索：阿里巴巴股价\r\n\r\n![](https://cdn.nlark.com/yuque/0/2025/png/1267930/1744871541850-5edfe256-b58a-49db-b144-fd08397dca28.png)\r\n\r\n博查AI Search API可以在提供网页信息的基础上，额外输出股价的结构化数据模态卡：\r\n\r\n![](https://cdn.nlark.com/yuque/0/2025/png/1267930/1744871541912-ead805e7-5c60-494c-a0c6-996177814db4.png)\r\n\r\n通过模态卡提供的结构化数据，可以进一步增强AI应用中用户对于时效性问题的回答准确性。', 'T', 'T', NULL, NULL, NULL, 'notContains', NULL), (1320584359766908928, 'AES 加解密工具', 'plugin_1320584359766908934', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/aes/execute', 1, '2025-12-23 10:50:46', '00A', 1, '2026-04-17 20:25:10', '用于将已进行AES加解密的文本内容进行AES加解密', NULL, '## 插件描述\r\n  此插件用于将已进行AES加解密的内容进行AES加解密\r\n## 插件使用说明\r\n1、text字段为待加(解)密的字符串内容\r\n2、aeskey字段为AES解密的密钥（加(解)密密钥要相同）\r\n3、decryptText字段为AES解密后的内容\r\n4、 encryptText字段为AES加密后的内容\r\n\r\n\r\n## 插件使用示例\r\n### 加密工具\r\n\r\n* 输入示例\r\n```json\r\n{\r\n  \"text\": \"加密内容\",\r\n  \"aesKey\": \"123456\"\r\n}\r\n```\r\n* 输出示例\r\n```json\r\n{\r\n  \"decryptText\": \"uH80HNAr0uRGC2Hjbw+0zw==\"\r\n}\r\n```\r\n### 解密工具\r\n\r\n* 输入示例\r\n```json\r\n{\r\n  \"text\": \"uH80HNAr0uRGC2Hjbw+0zw==\",\r\n  \"aesKey\": \"123456\"\r\n}\r\n```\r\n* 输出示例\r\n```json\r\n{\r\n  \"decryptText\": \"加密的内容\"\r\n}\r\n```', 'F', 'T', NULL, '/plugin/aes/detail', 'sdk', 'all', NULL), (1320651900203388928, '图片生成', 'plugin_1320651900203388928', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/douBaoText2Image/execute', 1, '2025-12-23 15:19:09', '00A', 1, '2026-04-17 20:28:47', '调用豆包大模型API，根据用户提供的文本提示词（prompt）自动生成对应的图片。', '[{\"name\":\"API密钥\",\"code\":\"apiKey\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"模型名称\",\"code\":\"modelCode\",\"value\":\"\",\"type\":\"header\"}]', '  ## 插件功能\r\n\r\n  本插件调用豆包大模型API，根据用户提供的文本提示词（prompt）自动生成对应的图片。\r\n\r\n  ## 主要特性\r\n\r\n  - **文本生成图片**：输入描述性文本，AI自动生成匹配的图片\r\n  - **灵活尺寸选择**：支持多种图片尺寸比例，适应不同使用场景\r\n\r\n  ## 推荐的图片尺寸\r\n\r\n  - `1024x1024`：正方形图片（1:1比例），通用场景推荐\r\n  - `1024x1792`：竖向图片（9:16比例），适合手机壁纸、竖屏展示\r\n  - `1792x1024`：横向图片（16:9比例），适合横幅、横屏展示', 'F', 'T', NULL, '/plugin/douBaoText2Image/detail', 'sdk', 'all', NULL), (1320653695025762304, '图片转换', 'plugin_1320653695025762304', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/imageConvert/execute', 1, '2025-12-23 15:26:17', '00A', 1, '2026-04-17 20:28:51', '图片格式转换插件 支持格式：PNG, JPEG, JPG, BMP, GIF', NULL, '  ## 插件描述\r\n\r\n  图片格式转换插件支持将图片文件在不同格式之间进行转换，支持PNG、JPEG、JPG、BMP、GIF五种常见图片格式。插件提供两种使用方式：文件上传方式和Base64编码方式，满足不同场景下的使用需求。\r\n\r\n  ## 使用场景\r\n\r\n  - **网站图片优化**：将大尺寸的PNG图片转换为JPEG格式，减小文件体积，提升网页加载速度\r\n  - **图片格式统一**：将不同来源的图片统一转换为指定格式，便于统一管理和处理\r\n  - **兼容性处理**：将不兼容的图片格式转换为目标系统支持的格式\r\n  - **批量图片处理**：在自动化流程中对图片进行格式转换，如将扫描件从BMP转换为PDF所需的JPEG格式\r\n  - **API集成场景**：通过Base64编码方式在API调用中直接传递图片数据进行格式转换\r\n\r\n  ## 参数说明\r\n\r\n  - **输入方式**：支持文件上传（multipart）和Base64编码（json）两种方式\r\n  - **目标格式**：必须指定目标格式，支持png、jpg、jpeg、bmp、gif五种格式\r\n  - **输出方式**：文件上传方式返回文件流，Base64方式返回包含base64数据、文件名、文件大小和格式的JSON对象', 'F', 'T', NULL, '/plugin/imageConvert/detail', 'sdk', 'all', NULL), (1320680622596415488, '图片压缩', 'plugin_1320680622588026880', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/imageCompress/execute', 1, '2025-12-23 17:13:17', '00A', 1, '2026-04-17 20:28:42', '对图片进行压缩并返回压缩后的base64数据', NULL, '## 插件描述\r\n\r\n  图片压缩插件支持对图片进行压缩处理，通过调整压缩质量和图片尺寸来减小文件体积。插件支持两种输入方式：文件上传和Base64编码，并提供灵活的压缩参数配置。压缩后的图片以Base64编码的data URI格式返回，同时返回压缩前后的文件大小、压缩率等统计信息，方便用户了解压缩效果。\r\n\r\n  ## 使用场景\r\n\r\n  - **网站图片优化**：压缩网站中的图片资源，减小文件体积，提升页面加载速度，改善用户体验\r\n  - **移动端图片处理**：在移动应用中压缩图片，减少存储空间占用和网络传输流量\r\n  - **批量图片处理**：在自动化流程中对大量图片进行压缩处理，如批量上传前的预处理\r\n  - **API集成场景**：通过Base64编码方式在API调用中直接传递图片数据进行压缩处理\r\n  - **存储空间优化**：压缩图片以节省云存储空间，降低存储成本\r\n  - **邮件附件优化**：压缩图片附件以符合邮件大小限制\r\n\r\n  ## 参数说明\r\n\r\n  - **输入方式**：支持文件上传（multipart）和Base64编码两种方式，两种方式至少需要提供一个\r\n  - **压缩质量**：取值范围0.0-1.0，数值越大质量越高但文件体积越大，推荐值0.8（平衡质量和体积）\r\n  - **尺寸缩放**：可设置最大宽度和最大高度，图片会按比例缩放，不超过设定的最大尺寸\r\n  - **输出格式**：返回JSON对象，包含压缩后的Base64数据（data URI格式）和压缩统计信息', 'F', 'T', NULL, '/plugin/imageCompress/detail', 'sdk', 'all', NULL), (1320682267971543041, '图片识别', 'plugin_1320682267971543040', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/imageAnalysis/execute', 1, '2025-12-23 17:19:49', '00A', 1, '2026-04-17 20:28:38', '图片理解插件是一个基于大模型的智能图片分析工具，能够根据用户上传的图片和问题描述，使用大模型进行深度图片分析并返回专业的分析结果。插件支持多种图片格式（PNG、JPEG、BMP、WebP），提供文件上传和Base64编码两种图片输入方式，具备专业的视觉分析能力，能够理解图片中的内容、场景、对象、文字等各类视觉元素。', NULL, '## 插件描述\r\n\r\n  图片理解插件是一个基于大模型的智能图片分析工具，能够根据用户上传的图片和问题描述，使用大模型进行深度图片分析并返回专业的分析结果。插件支持多种图片格式（PNG、JPEG、BMP、WebP），提供文件上传和Base64编码两种图片输入方式，具备专业的视觉分析能力，能够理解图片中的内容、场景、对象、文字等各类视觉元素。\r\n\r\n  ## 使用场景\r\n\r\n  - **图片内容识别**：识别图片中的主体对象、场景、人物、文字等元素\r\n  - **图片问答**：回答用户关于图片的具体问题，如\"图片中有什么？\"、\"图片的颜色搭配如何？\"等\r\n  - **图片描述生成**：自动生成图片的详细文字描述\r\n  - **图片分析报告**：对图片进行多维度分析，包括视觉元素、构图、风格等\r\n  - **图片信息提取**：从图片中提取关键信息，如文字内容、数据表格等\r\n  - **图片质量评估**：评估图片的质量、清晰度、构图等\r\n\r\n  ## 参数说明\r\n\r\n  插件主要包含以下参数：\r\n  - **llm**：大模型配置参数，包含模型地址、模型名称和认证信息，必填\r\n  - **prompt**：用户的问题描述或分析需求，必填\r\n  - **image**：图片文件（文件上传方式），可选\r\n  - **imageBase64**：Base64编码的图片，可选\r\n  - **systemPrompt**：自定义系统提示词，可选，不配置时使用默认的专业视觉分析专家提示词\r\n\r\n  注意：image 和 imageBase64 至少需要提供一个，用于指定要分析的图片。', 'F', 'T', NULL, '/plugin/imageAnalysis/detail', 'sdk', 'all', NULL), (1320683444419289089, '证件识别', 'plugin_1320683444419289088', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/certificateIdentify/execute', 1, '2025-12-23 17:24:30', '00A', 1, '2026-04-17 20:28:28', '提供各类证件的OCR识别与信息提取功能，包括身份证、银行卡、护照等。', NULL, '## 插件描述\r\n  提供各类证件的OCR识别与信息提取功能，包括身份证、银行卡、护照等。\r\n\r\n  ## 使用场景\r\n  - **身份证识别**：用于身份验证、实名认证等场景\r\n  - **银行卡识别**：用于快速录入银行卡信息、在线支付等场景\r\n  - **护照识别**：用于出入境管理、签证申请等场景\r\n  - **营业执照识别**：用于企业信息录入、工商审核等场景\r\n  - **学位证书识别**：用于学历验证、教育背景核实等场景\r\n  - **驾驶证识别**：用于驾驶员信息管理、交通管理等场景\r\n  - **户口本识别**：用于户籍管理、人口统计等场景\r\n  - **组织机构代码证识别**：用于机构信息验证、企业资质审核等场景\r\n\r\n  ## 参数说明\r\n  - **file**（图片文件）：\r\n    - 类型：file\r\n    - 说明：需要识别的证件图片文件\r\n    - 必填：否（与base64二选一）\r\n\r\n  - **base64**（图片base64）：\r\n    - 类型：string\r\n    - 说明：需要识别的证件图片的base64编码\r\n    - 必填：否（与file二选一）', 'F', 'T', NULL, '/plugin/certificateIdentify/detail', 'sdk', 'all', NULL), (1320685148044910593, '表格识别', 'plugin_1320685148044910592', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/tableExtracted/execute', 1, '2025-12-23 17:31:16', '00A', 1, '2026-04-17 20:28:33', '表格提取插件，支持从Word文档、PDF文件和图片中自动识别并提取表格数据，将表格内容转换为结构化的HTML格式，便于进一步处理和分析。', NULL, '## 插件描述\r\n  表格提取插件，支持从Word文档、PDF文件和图片中自动识别并提取表格数据，将表格内容转换为结构化的HTML格式，便于进一步处理和分析。\r\n\r\n  ## 使用场景\r\n  - **文档处理**：从Word、PDF或图片中提取表格数据，用于数据分析和处理\r\n  - **数据录入**：自动识别并提取表格内容，减少人工录入工作\r\n  - **报表分析**：从各种格式的文档中提取表格进行进一步分析\r\n  - **数据迁移**：将不同格式文档中的表格数据迁移到其他系统\r\n\r\n  ## 参数说明\r\n  - **file**（文件）：\r\n    - 类型：file\r\n    - 说明：需要提取表格的文件（支持Word、PDF、图片格式）\r\n    - 必填：是（与base64二选一）\r\n\r\n  - **base64**（文件内容）：\r\n    - 类型：string\r\n    - 说明：文件内容的Base64编码\r\n    - 必填：是（与file二选一）', 'F', 'T', NULL, '/plugin/tableExtracted/detail', 'sdk', 'all', NULL), (1320685882006167552, '快递查询', 'plugin_1320685882001973248', 'data:image/png;base64,', 1320583828336009216, 1320646999213690880, 'tool', '1', 'local', '/plugin/kuaidiQuery/execute', 1, '2025-12-23 17:34:11', '00A', 1, '2026-04-17 20:31:28', '快递查询插件基于快递100 API，提供快递物流信息查询功能。', '[{\"name\":\"快递100客户编码\",\"code\":\"customer\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"密钥\",\"code\":\"key\",\"value\":\"\",\"type\":\"header\"}]', '  ## 插件描述\r\n\r\n  快递查询插件基于快递100 API，提供快递物流信息查询功能。支持两种查询模式：\r\n  - **普通查询**：需要提供快递公司编码和快递单号进行查询\r\n  - **智能查询**：仅需提供快递单号，系统会自动识别快递公司并查询物流信息\r\n\r\n  ## 使用场景\r\n\r\n  - 电商平台订单物流跟踪\r\n  - 企业内部物流管理系统\r\n  - 个人快递查询助手\r\n  - 物流信息监控和提醒系统\r\n\r\n  ## 参数说明\r\n\r\n  插件需要配置以下参数：\r\n  - **customer**：快递100客户编码，用于API身份认证\r\n  - **key**：快递100 API密钥，用于签名验证', 'T', 'T', NULL, '/plugin/kuaidiQuery/detail', 'sdk', 'all', NULL), (1320694533940961281, '微信公众号', 'plugin_1320694533940961280', 'data:image/png;base64,', 1320583828336009216, 1320647328315559936, 'tool', '1', 'local', '/plugin/weChatMp/execute', 1, '2025-12-23 18:08:34', '00A', 1, '2026-04-17 20:28:20', '微信公众号相关功能插件，提供微信公众号的完整功能支持，包括获取访问令牌、素材管理、图文消息处理、文章发布与管理等操作。\r\n  ', NULL, ' ## 插件描述\r\n  微信公众号相关功能插件，提供微信公众号的完整功能支持，包括获取访问令牌、素材管理、图文消息处理、文章发布与管理等操作。\r\n\r\n  ## 使用场景\r\n  - **公众号运营**：用于日常的微信公众号内容发布和管理\r\n  - **素材管理**：上传、删除和管理公众号的多媒体素材\r\n  - **内容发布**：创建图文草稿、发布文章和管理已发布内容\r\n  - **文章状态监控**：查询已发布文章的状态和详细信息\r\n  - **自动化运营**：通过API实现公众号内容的自动化发布和管理', 'F', 'T', NULL, '/plugin/weChatMp/detail', 'sdk', 'all', NULL), (1320712579427860480, '哔哩哔哩', 'plugin_1320712578630942720', 'data:image/png;base64,', 1320583828336009216, 1320647328315559936, 'tool', '1', 'local', '/plugin/bilibili/execute', 1, '2025-12-23 19:20:16', '00A', 1, '2026-04-17 20:28:14', '哔哩哔哩视频相关功能插件，提供搜索哔哩哔哩视频和获取哔哩哔哩热榜数据的功能。', NULL, '## 插件描述\r\n  哔哩哔哩视频相关功能插件，提供搜索哔哩哔哩视频和获取哔哩哔哩热榜数据的功能。\r\n\r\n  ## 使用场景\r\n  - **视频搜索**：根据关键词搜索哔哩哔哩平台的视频内容\r\n  - **热门内容分析**：获取哔哩哔哩热榜数据，分析当前热门视频趋势\r\n  - **内容推荐**：为用户提供哔哩哔哩平台的视频推荐服务\r\n  - **数据收集**：收集哔哩哔哩视频的播放量、评论数、点赞数等相关数据\r\n  - **竞品分析**：分析哔哩哔哩平台上的热门内容和趋势\r\n\r\n  ## 参数描述\r\n  - **cookie**（Cookie信息）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：访问哔哩哔哩API所需的Cookie信息，用于身份验证和访问权限\r\n\r\n  - **keyword**（搜索关键词）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：用于搜索哔哩哔哩视频的关键词\r\n\r\n  - **pageNum**（页码）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：搜索结果的页码，默认为第一页\r\n\r\n  - **pageSize**（每页数量）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：每页返回的视频数量，默认为10个\r\n\r\n  - **total**（查询总数）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：获取热榜数据时指定查询的视频总数', 'F', 'T', NULL, '/plugin/bilibili/detail', 'sdk', 'all', NULL), (1320713569015169024, '网易新闻', 'plugin_1320713569010974720', 'data:image/png;base64,', 1320583828336009216, 1320647235042627584, 'tool', '1', 'local', '/plugin/netEase/execute', 1, '2025-12-23 19:24:12', '00A', 1, '2026-04-17 20:29:51', '网易新闻相关工具集，提供获取网易新闻热榜等功能，实时获取当前热门新闻信息。', NULL, '## 插件描述\r\n  网易相关工具集，提供获取网易新闻热榜等功能，实时获取当前热门新闻信息。\r\n\r\n  ## 使用场景\r\n  - **新闻资讯获取**：获取最新的网易新闻热榜，了解当前热门事件\r\n  - **舆情监控**：监控网络热点话题和新闻趋势\r\n  - **内容推荐**：为用户提供当前热门新闻内容推荐\r\n  - **数据分析**：分析新闻热度和传播趋势\r\n  - **信息聚合**：将网易新闻热榜信息聚合到其他平台或应用中\r\n\r\n  ## 参数说明\r\n  该插件目前无需输入参数，直接调用即可获取网易新闻热榜数据。', 'F', 'T', NULL, '/plugin/netEase/detail', 'sdk', 'all', NULL), (1320714720607469569, '今日头条', 'plugin_1320714720607469568', 'data:image/png;base64,', 1320583828336009216, 1320647235042627584, 'tool', '1', 'local', '/plugin/toutiao/execute', 1, '2025-12-23 19:28:47', '00A', 1, '2026-04-17 20:29:55', '今日头条相关工具插件，提供获取今日头条热搜榜数据的功能，实时获取当前热门话题和新闻信息。', NULL, '## 插件描述\r\n  今日头条相关工具插件，提供获取今日头条热搜榜数据的功能，实时获取当前热门话题和新闻信息。\r\n\r\n  ## 使用场景\r\n  - **热点追踪**：实时获取今日头条平台的热门话题和新闻\r\n  - **舆情监控**：监控网络热点话题和舆论趋势\r\n  - **内容推荐**：为用户提供当前热门内容推荐\r\n  - **市场分析**：分析热门话题的热度和传播趋势\r\n  - **信息聚合**：将今日头条热搜榜信息聚合到其他平台或应用中\r\n\r\n  ## 参数说明\r\n  该插件目前无需输入参数，直接调用即可获取今日头条热搜榜数据。', 'F', 'T', NULL, '/plugin/toutiao/detail', 'sdk', 'all', NULL);
INSERT INTO `pt_plugin` VALUES (1320715792868704256, '微博', 'plugin_1320715792747069440', 'data:image/png;base64,', 1320583828336009216, 1320647235042627584, 'tool', '1', 'local', '/plugin/weibo/execute', 1, '2025-12-23 19:33:02', '00A', 1, '2026-04-17 20:30:03', '微博相关工具插件，提供获取微博实时热搜列表的功能，实时获取当前微博平台的热门话题和热搜内容。', NULL, ' ## 插件描述\r\n  微博相关工具插件，提供获取微博实时热搜列表的功能，实时获取当前微博平台的热门话题和热搜内容。\r\n\r\n  ## 使用场景\r\n  - **热点追踪**：实时获取微博平台的热门话题和热搜内容\r\n  - **舆情监控**：监控微博平台的舆论趋势和热门话题\r\n  - **内容推荐**：为用户提供当前微博热搜内容推荐\r\n  - **市场分析**：分析微博热搜话题的热度和传播趋势\r\n  - **信息聚合**：将微博热搜信息聚合到其他平台或应用中\r\n\r\n  ## 参数说明\r\n  该插件目前无需输入参数，直接调用即可获取微博实时热搜列表数据。', 'F', 'T', NULL, '/plugin/weibo/detail', 'sdk', 'all', NULL), (1320716356641882112, '知乎', 'plugin_1320716356620910592', 'data:image/png;base64,', 1320583828336009216, 1320647235042627584, 'tool', '1', 'local', '/plugin/zhiHu/execute', 1, '2025-12-23 19:35:17', '00A', 1, '2026-04-17 20:29:59', '知乎相关工具插件，提供获取知乎热榜的功能，实时获取当前知乎平台的热门话题和内容。', NULL, ' ## 插件描述\r\n  知乎相关工具插件，提供获取知乎热榜的功能，实时获取当前知乎平台的热门话题和内容。\r\n\r\n  ## 使用场景\r\n  - **热点追踪**：实时获取知乎平台的热门话题和讨论内容\r\n  - **舆情监控**：监控知乎平台的舆论趋势和热门讨论\r\n  - **内容推荐**：为用户提供当前知乎热榜内容推荐\r\n  - **市场分析**：分析知乎热榜话题的热度和讨论趋势\r\n  - **信息聚合**：将知乎热榜信息聚合到其他平台或应用中\r\n\r\n  ## 参数说明\r\n  - **cookie**（Cookie数据）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：访问知乎API所需的Cookie数据，用于身份验证和访问权限', 'F', 'T', NULL, '/plugin/zhiHu/detail', 'sdk', 'all', NULL), (1320716900714414080, '抖音', 'plugin_1320716900710219776', 'data:image/png;base64,', 1320583828336009216, 1320647328315559936, 'tool', '1', 'local', '/plugin/douyin/execute', 1, '2025-12-23 19:37:26', '00A', 1, '2026-04-17 20:28:09', '抖音相关工具集，提供抖音热榜、评论获取及视频解析等功能，帮助用户获取抖音平台的热门内容、评论数据和视频内容解析。', NULL, '## 插件描述\r\n  抖音相关工具集，提供抖音热榜、评论获取及视频解析等功能，帮助用户获取抖音平台的热门内容、评论数据和视频内容解析。\r\n\r\n  ## 使用场景\r\n  - **热点追踪**：获取抖音热榜数据，了解当前热门话题和视频\r\n  - **评论分析**：获取抖音视频的评论列表，进行用户反馈和舆情分析\r\n  - **内容解析**：解析抖音视频内容，提取文字和截图信息\r\n  - **数据收集**：收集抖音平台的热度数据和用户互动信息\r\n  - **内容推荐**：基于抖音热榜数据为用户提供内容推荐\r\n\r\n  ## 参数说明\r\n  - **boardType**（榜单类型）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：指定榜单类型，0表示抖音热榜，2表示其他榜\r\n\r\n  - **boardSubType**（子榜单类型）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：指定子榜单类型，如2表示娱乐榜，4表示社会榜，hotspot_challenge表示挑战榜，seeding表示种草榜等\r\n\r\n  - **url**（抖音视频地址）：\r\n    - 类型：string\r\n    - 必填：是（在获取评论和视频解析功能中）\r\n    - 说明：抖音视频的完整地址链接\r\n\r\n  - **pageSize**（每页数量）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：每页返回的评论数量，默认为20\r\n\r\n  - **pageNum**（页数）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：查询的页数，默认为0，从0开始计数\r\n\r\n  - **analysisMode**（解析模式）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：视频解析模式，1表示音频解析，2表示音频解析+截图，默认为1', 'F', 'T', NULL, '/plugin/douyin/detail', 'sdk', 'all', NULL), (1320720234657611776, '邮件发送', 'plugin_1320720234653417472', 'data:image/png;base64,', 1320583828336009216, 1320647133439807488, 'tool', '1', 'local', '/plugin/smtpEmail/execute', 1, '2025-12-23 19:50:41', '00A', 1, '2026-04-17 20:28:03', '邮件发送插件，提供发送SMTP邮件的功能，支持HTML内容和附件/内嵌图片，可以满足各种邮件发送需求。', NULL, '## 插件描述\r\n  邮件发送插件，提供发送SMTP邮件的功能，支持HTML内容和附件/内嵌图片，可以满足各种邮件发送需求。\r\n\r\n  ## 使用场景\r\n  - **系统通知**：向用户发送系统通知、提醒和确认邮件\r\n  - **营销邮件**：发送营销推广邮件和活动通知\r\n  - **业务邮件**：处理各种业务相关的邮件发送需求\r\n  - **报告发送**：定期发送报表和分析结果邮件\r\n  - **用户注册**：处理用户注册验证和欢迎邮件\r\n\r\n  ## 参数说明\r\n  - **host**（SMTP服务器地址）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：SMTP邮件服务器的地址\r\n\r\n  - **port**（SMTP端口）：\r\n    - 类型：integer\r\n    - 必填：是\r\n    - 说明：SMTP邮件服务器的端口号\r\n\r\n  - **username**（发件人邮箱）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：发件人邮箱地址\r\n\r\n  - **password**（发件人密码）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：发件人邮箱密码或授权码\r\n\r\n  - **protocol**（协议）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：邮件协议，默认为smtp\r\n\r\n  - **encoding**（编码）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：邮件编码格式，默认为UTF-8\r\n\r\n  - **to**（收件人邮箱列表）：\r\n    - 类型：array\r\n    - 必填：是\r\n    - 说明：收件人邮箱地址列表\r\n\r\n  - **subject**（邮件主题）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：邮件主题或标题\r\n\r\n  - **content**（邮件内容）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：邮件正文内容，支持HTML格式\r\n\r\n  - **fileIds**（附件文件列表）：\r\n    - 类型：array\r\n    - 必填：否\r\n    - 说明：附件文件列表，如果HTML内容中使用cid:文件名引用，则作为内嵌图片\r\n', 'F', 'T', NULL, '/plugin/smtpEmail/detail', 'sdk', 'all', NULL), (1320721269279162368, '企业微信消息发送', 'plugin_1320721269224636416', 'data:image/png;base64,', 1320583828336009216, 1320647133439807488, 'tool', '1', 'local', '/plugin/weChatBot/execute', 1, '2025-12-23 19:54:48', '00A', 1, '2026-04-17 20:26:57', '微信机器人插件，提供发送微信机器人通知的功能，支持多种消息类型，包括文本、Markdown、图片、文件、语音、图文和模板卡片等。', NULL, '## 插件描述\r\n  微信机器人插件，提供发送微信机器人通知的功能，支持多种消息类型，包括文本、Markdown、图片、文件、语音、图文和模板卡片等。\r\n\r\n  ## 使用场景\r\n  - **系统通知**：向微信群发送系统告警、监控通知等\r\n  - **工作提醒**：发送工作日程、会议提醒等\r\n  - **数据报告**：定期向群组发送数据报表和业务指标\r\n  - **营销推广**：发送营销活动和产品推广信息\r\n  - **自动化流程**：在自动化流程中发送状态更新和结果通知\r\n\r\n  ## 参数说明\r\n  - **key**（webhook地址key）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：Webhook地址的key，用于识别特定的机器人\r\n\r\n  - **secret**（密钥）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：用于签名验证的密钥\r\n\r\n  - **corpId**（企业ID）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：企业微信的企业ID\r\n\r\n  - **message**（消息对象）：\r\n    - 类型：object\r\n    - 必填：是\r\n    - 说明：要发送的消息内容\r\n    - 子参数：\r\n      - msgType：消息类型（必填）\r\n      - text：文本消息\r\n        - content：消息内容（必填）\r\n        - mentionedList：@用户ID列表\r\n        - mentionedMobileList：@手机号列表\r\n      - markdown：Markdown消息\r\n        - content：Markdown内容（必填）\r\n      - image：图片消息\r\n        - picUrl：图片URL（必填）\r\n        - mediaId：图片mediaId（必填）\r\n      - file：文件消息\r\n        - mediaId：媒体ID（必填）\r\n      - voice：语音消息\r\n        - mediaId：媒体ID（必填）\r\n      - news：图文消息\r\n        - articles：图文消息列表（必填）\r\n          - title：标题（必填）\r\n          - description：描述\r\n          - url：点击后跳转的链接（必填）\r\n          - picurl：图文消息的图片链接\r\n      - templateCard：模板卡片\r\n        - cardType：卡片类型（必填）\r\n        - subTitleText：二级普通文本\r\n        - source：卡片来源样式信息\r\n        - mainTitle：模版卡片的主要内容（必填）\r\n        - emphasisContent：关键数据样式\r\n        - quoteArea：引用文献样式\r\n        - horizontalContentList：二级标题+文本列表\r\n        - jumpList：跳转指引样式的列表\r\n        - cardAction：卡片跳转（必填）\r\n        - cardImage：图片样式（必填）\r\n        - imageTextArea：左图右文样式\r\n        - verticalContentList：卡片二级垂直内容', 'F', 'T', NULL, '/plugin/weChatBot/detail', 'sdk', 'all', NULL), (1320722150036865024, '钉钉消息发送', 'plugin_1320722150028476416', 'data:image/png;base64,', 1320583828336009216, 1320647133439807488, 'tool', '1', 'local', '/plugin/dingtalk/execute', 1, '2025-12-23 19:58:18', '00A', 1, '2026-04-17 20:27:58', '钉钉相关插件，提供群机器人通知和工作通知功能，支持多种消息类型，包括文本、Markdown、链接、ActionCard和FeedCard等。', NULL, '## 插件描述\r\n  钉钉相关插件，提供群机器人通知和工作通知功能，支持多种消息类型，包括文本、Markdown、链接、ActionCard和FeedCard等。\r\n\r\n  ## 使用场景\r\n  - **系统通知**：向钉钉群发送系统告警、监控通知等\r\n  - **工作提醒**：发送工作日程、会议提醒等\r\n  - **数据报告**：定期向群组发送数据报表和业务指标\r\n  - **审批通知**：发送审批流程和待办事项通知\r\n  - **自动化流程**：在自动化流程中发送状态更新和结果通知\r\n\r\n  ## 参数说明\r\n  - **accessToken**（webhook地址accessToken）：\r\n    - 类型：string\r\n    - 必填：是（在机器人通知功能中）\r\n    - 说明：Webhook地址的accessToken，用于识别特定的机器人\r\n\r\n  - **secret**（密钥）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：用于签名验证的密钥\r\n\r\n  - **at**（被@的人）：\r\n    - 类型：object\r\n    - 必填：否\r\n    - 说明：指定被@的人员信息\r\n    - 子参数：\r\n      - atMobiles：被@的人手机号列表\r\n      - atUserIds：被@的人userId列表\r\n      - isAtAll：是否@所有人\r\n\r\n  - **message**（消息内容）：\r\n    - 类型：object\r\n    - 必填：是\r\n    - 说明：要发送的消息内容\r\n    - 子参数：\r\n      - msgType：消息类型（必填）\r\n      - text：文本消息\r\n        - content：文本内容\r\n      - markdown：Markdown消息\r\n        - title：首屏会话透出的展示内容\r\n        - text：markdown格式的消息\r\n      - link：链接消息\r\n        - messageUrl：消息跳转URL\r\n        - picUrl：图片URL\r\n        - title：消息标题\r\n        - text：消息内容\r\n      - actionCard：actionCard消息\r\n        - title：标题\r\n        - text：消息内容\r\n        - singleTitle：单个按钮的标题\r\n        - singleUrl：单个按钮的url\r\n        - btnOrientation：按钮排列方向\r\n        - btns：按钮列表\r\n      - feedCard：feedCard消息\r\n        - links：链接列表\r\n\r\n  - **agentId**（应用ID）：\r\n    - 类型：integer\r\n    - 必填：是（在工作通知功能中）\r\n    - 说明：钉钉应用的ID\r\n\r\n  - **appKey**（应用key）：\r\n    - 类型：string\r\n    - 必填：是（在工作通知功能中）\r\n    - 说明：钉钉应用的key\r\n\r\n  - **appSecret**（应用密钥）：\r\n    - 类型：string\r\n    - 必填：是（在工作通知功能中）\r\n    - 说明：钉钉应用的密钥\r\n\r\n  - **userIdList**（接收人ID列表）：\r\n    - 类型：array\r\n    - 必填：否（在工作通知功能中）\r\n    - 说明：接收通知的用户ID列表\r\n\r\n  - **deptIdList**（部门ID列表）：\r\n    - 类型：array\r\n    - 必填：否（在工作通知功能中）\r\n    - 说明：接收通知的部门ID列表\r\n\r\n  - **toAllUser**（是否发送给企业全部用户）：\r\n    - 类型：boolean\r\n    - 必填：否（在工作通知功能中）\r\n    - 说明：是否发送给企业全部用户', 'F', 'T', NULL, '/plugin/dingtalk/detail', 'sdk', 'all', NULL);
INSERT INTO `pt_plugin` VALUES (1320725527177199616, '数组Map互转', 'plugin_1320725527173005312', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/arrayMapTransform/execute', 1, '2025-12-23 20:11:43', '00A', 1, '2026-04-17 20:28:55', '提供数组与Map之间的相互转换功能', NULL, '  ## 插件描述\r\n\r\n  提供数组与Map之间的相互转换功能，支持两种转换方向：\r\n\r\n  - **数组转Map**：将对象数组转换为Map结构，支持指定键字段和值字段\r\n  - **Map转数组**：将Map结构转换为对象数组，每个数组元素包含键和值两个属性\r\n\r\n  ## 使用场景\r\n\r\n  - 数据格式转换：在不同数据结构之间进行转换，满足不同业务需求\r\n  - 数据查询优化：将数组转换为Map后，可以通过键快速查找对应的值\r\n  - 数据展示：将Map转换为数组后，便于进行列表展示和遍历操作\r\n  - 接口适配：在不同系统间传递数据时，需要转换数据格式\r\n\r\n  ## 参数说明\r\n\r\n  - **listToMap工具**：\r\n    - `list`：待转换的对象数组，必填\r\n    - `leftKey`：Map的键字段名，必填，用于从数组元素中提取作为Map的键\r\n    - `rightKey`：Map的值字段名，可选，为空时整个对象作为Map的值\r\n\r\n  - **mapToArray工具**：\r\n    - `map`：待转换的Map对象，必填\r\n    - `leftKey`：数组对象中的键属性名，必填，用于存储Map的键\r\n    - `rightKey`：数组对象中的值属性名，必填，用于存储Map的值', 'F', 'T', NULL, '/plugin/arrayMapTransform/detail', 'sdk', 'all', NULL), (1320725933374570497, '数组筛选', 'plugin_1320725933374570496', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/arrayFilter/execute', 1, '2025-12-23 20:13:20', '00A', 1, '2026-04-17 20:29:02', '数组筛选插件，提供快速获取数组中匹配特定条件的值的功能，方便进行数据筛选和提取操作。', NULL, '## 插件描述\r\n  数组筛选插件，提供快速获取数组中匹配特定条件的值的功能，方便进行数据筛选和提取操作。\r\n\r\n  ## 使用场景\r\n  - **数据过滤**：从大量数据中筛选出符合特定条件的记录\r\n  - **列表处理**：对对象列表进行条件筛选，提取所需数据\r\n  - **数值筛选**：根据数值条件筛选数据，如价格范围、时间范围等\r\n  - **文本匹配**：根据关键词筛选包含特定文本的条目\r\n  - **数据预处理**：在数据分析前对原始数据进行筛选和清洗\r\n\r\n  ## 参数说明\r\n  - **array**（待筛选的数组）：\r\n    - 类型：array\r\n    - 必填：是\r\n    - 说明：需要进行筛选的数组或List数据\r\n\r\n  - **fieldName**（字段名）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：当数组元素是对象时，指定要比较的字段名；如果为null或空字符串，则直接比较数组元素本身\r\n\r\n  - **operator**（操作符）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：指定筛选操作符，可选值包括：\r\n      - `大于`：筛选大于指定值的元素\r\n      - `大于等于`：筛选大于或等于指定值的元素\r\n      - `小于`：筛选小于指定值的元素\r\n      - `小于等于`：筛选小于或等于指定值的元素\r\n      - `等于`：筛选等于指定值的元素\r\n      - `包含`：筛选包含指定值的元素（适用于字符串或集合类型）\r\n      - `不包含`：筛选不包含指定值的元素（适用于字符串或集合类型）\r\n\r\n  - **value**（比较值）：\r\n    - 类型：any\r\n    - 必填：否\r\n    - 说明：用于与数组元素进行比较的值。对于\"大于\"、\"大于等于\"、\"小于\"、\"小于等于\"、\"等于\"操作符，此参数必填；对于\"包含\"和\"不包含\"操作符，可以为null\r\n', 'F', 'T', NULL, '/plugin/arrayFilter/detail', 'sdk', 'all', NULL), (1320726957711687680, '文本Base64编码', 'plugin_1320726957703299072', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/base64/execute', 1, '2025-12-23 20:17:24', '00A', 1, '2026-04-17 20:29:07', 'Base64 编解码工具集，提供字符串与Base64编码之间的相互转换功能，用于数据的编码和解码操作。', NULL, '## 插件描述\r\n  Base64 编解码工具集，提供字符串与Base64编码之间的相互转换功能，用于数据的编码和解码操作。\r\n\r\n  ## 使用场景\r\n  - **数据传输**：在网络传输中对二进制数据进行编码，确保数据完整性\r\n  - **数据存储**：将二进制数据转换为文本格式进行存储\r\n  - **URL传输**：在URL中安全传输特殊字符数据\r\n  - **文件上传**：将文件内容转换为Base64格式进行传输\r\n  - **加密预处理**：在加密前对数据进行Base64编码\r\n\r\n  ## 参数说明\r\n  - **text**（待编码的文本）：\r\n    - 类型：string\r\n    - 必填：是（在Base64编码功能中）\r\n    - 说明：需要进行Base64编码的原始文本内容\r\n\r\n  - **encoderText**（待解码的文本）：\r\n    - 类型：string\r\n    - 必填：是（在Base64解码功能中）\r\n    - 说明：需要进行解码的Base64编码文本', 'F', 'T', NULL, '/plugin/base64/detail', 'sdk', 'all', NULL), (1320727358762647552, 'SHA加解密', 'plugin_1320727358758453248', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/shaHash/execute', 1, '2025-12-23 20:19:00', '00A', 1, '2026-04-17 20:29:12', 'SHA哈希工具集，提供SHA1哈希加密和验证功能，用于数据完整性校验和安全验证。', NULL, '## 插件描述\r\n  SHA哈希工具集，提供SHA1哈希加密和验证功能，用于数据完整性校验和安全验证。\r\n\r\n  ## 使用场景\r\n  - **数据完整性校验**：验证文件或数据在传输过程中是否被篡改\r\n  - **密码存储**：对用户密码进行哈希处理后存储\r\n  - **数字签名**：在数字签名过程中对数据进行哈希处理\r\n  - **安全验证**：验证数据的原始性和完整性\r\n  - **去重处理**：通过哈希值快速判断数据是否重复\r\n\r\n  ## 参数说明\r\n  - **text**（待加密内容）：\r\n    - 类型：string\r\n    - 必填：是（在SHA1哈希加密和验证功能中）\r\n    - 说明：需要进行SHA1哈希加密的原始文本内容\r\n\r\n  - **hash**（已加密的SHA1密文）：\r\n    - 类型：string\r\n    - 必填：是（在SHA1哈希验证功能中）\r\n    - 说明：已加密的SHA1密文（40位十六进制字符串），用于与输入文本的哈希值进行比较\r\n', 'F', 'T', NULL, '/plugin/shaHash/detail', 'sdk', 'all', NULL), (1320727708357885952, 'MD5加解密', 'plugin_1320727708353691648', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/md5Hash/execute', 1, '2025-12-23 20:20:23', '00A', 1, '2026-04-17 20:29:16', 'MD5哈希工具集，提供MD5哈希加密和验证功能，用于数据完整性校验和安全验证。', NULL, '## 插件描述\r\n  MD5哈希工具集，提供MD5哈希加密和验证功能，用于数据完整性校验和安全验证。\r\n\r\n  ## 使用场景\r\n  - **数据完整性校验**：验证文件或数据在传输过程中是否被篡改\r\n  - **密码存储**：对用户密码进行哈希处理后存储（注意：由于MD5安全性较低，建议用于非关键场景）\r\n  - **数字签名**：在数字签名过程中对数据进行哈希处理\r\n  - **安全验证**：验证数据的原始性和完整性\r\n  - **去重处理**：通过哈希值快速判断数据是否重复\r\n  - **快速比较**：通过MD5值快速比较两个文件或数据是否相同\r\n\r\n  ## 参数说明\r\n  - **text**（待加密内容）：\r\n    - 类型：string\r\n    - 必填：是（在MD5哈希加密和验证功能中）\r\n    - 说明：需要进行MD5哈希加密的原始文本内容\r\n\r\n  - **hash**（已加密的MD5密文）：\r\n    - 类型：string\r\n    - 必填：是（在MD5哈希验证功能中）\r\n    - 说明：已加密的MD5密文（32位十六进制字符串），用于与输入文本的哈希值进行比较', 'F', 'T', NULL, '/plugin/md5Hash/detail', 'sdk', 'all', NULL), (1320728183161487360, '链接提取', 'plugin_1320728183157293056', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/linkExtractor/execute', 1, '2025-12-23 20:22:16', '00A', 1, '2026-04-17 20:29:21', '链接提取工具，提供从文本内容中提取HTTP/HTTPS链接的功能，能够识别并提取文本中的所有网络链接。', NULL, '## 插件描述\r\n  链接提取工具，提供从文本内容中提取HTTP/HTTPS链接的功能，能够识别并提取文本中的所有网络链接。\r\n\r\n  ## 使用场景\r\n  - **内容分析**：从大量文本中提取网络链接进行分析\r\n  - **信息抓取**：从网页内容、社交媒体帖子等提取链接资源\r\n  - **数据清洗**：在数据处理过程中提取有用的链接信息\r\n  - **安全检测**：检测文本中可能存在的恶意链接\r\n  - **资源整理**：从文档或文章中提取引用的链接资源\r\n\r\n  ## 参数说明\r\n  - **text**（待处理的文本内容）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：需要从中提取HTTP/HTTPS链接的原始文本内容', 'F', 'T', NULL, '/plugin/linkExtractor/detail', 'sdk', 'all', NULL), (1320728674935242753, '水印生成', 'plugin_1320728674935242752', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/watermark/execute', 1, '2025-12-23 20:24:14', '00A', 1, '2026-04-17 20:30:24', '水印生成插件，提供图片和文档水印生成功能，支持文字和图片水印，保护文档和图片的版权。', NULL, '## 插件描述\r\n  水印生成插件，提供图片和文档水印生成功能，支持文字和图片水印，保护文档和图片的版权。\r\n\r\n  ## 使用场景\r\n  - **版权保护**：为图片和文档添加版权水印，防止未经授权的使用\r\n  - **文档标识**：为机密文档添加标识水印，如\"机密\"、\"草稿\"等\r\n  - **品牌宣传**：在图片上添加品牌标识或公司名称水印\r\n  - **防篡改**：为重要文档添加水印，以验证文档的完整性\r\n  - **内容标记**：为图片或文档添加特定标记，如\"样本\"、\"预览\"等\r\n\r\n  ## 参数说明\r\n  - **file**（原图片/文档文件）：\r\n    - 类型：file\r\n    - 必填：是（与fileUrl二选一）\r\n    - 说明：需要添加水印的原始图片或文档文件\r\n\r\n  - **fileUrl**（原图片/文档文件URL）：\r\n    - 类型：string\r\n    - 必填：是（与file二选一）\r\n    - 说明：需要添加水印的原始图片或文档文件的URL地址\r\n\r\n  - **watermarkText**（水印文本内容）：\r\n    - 类型：string\r\n    - 必填：是（在图片水印功能中，或在文档水印功能中当未提供watermarkImage时）\r\n    - 说明：要添加的水印文本内容\r\n\r\n  - **watermarkImage**（水印图片文件）：\r\n    - 类型：file\r\n    - 必填：是（在文档水印功能中当未提供watermarkText时）\r\n    - 说明：作为水印的图片文件（仅部分文档格式支持）\r\n\r\n  - **position**（水印位置）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：水印位置，可选值包括：\r\n      - top-left：左上角\r\n      - top-right：右上角\r\n      - bottom-left：左下角\r\n      - bottom-right：右下角\r\n      - center：居中\r\n      - repeat：重复显示\r\n      - 默认值：图片水印为bottom-right，文档水印为center\r\n\r\n  - **fontSize**（字体大小）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：水印文字的字体大小，默认为24\r\n\r\n  - **color**（字体颜色）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：水印文字的颜色，支持十六进制颜色值（如#FF0000）、颜色名称（如red）或rgb格式（如rgb(255,0,0)），默认为灰色\r\n\r\n  - **opacity**（透明度）：\r\n    - 类型：number\r\n    - 必填：否\r\n    - 说明：水印的透明度，范围为0.0-1.0，默认为0.5\r\n\r\n  - **angle**（旋转角度）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：水印的旋转角度，范围为0-360，默认为0（图片水印）或-45（文档水印）\r\n\r\n  - **spacing**（间距倍数）：\r\n    - 类型：number\r\n    - 必填：否\r\n    - 说明：重复水印时的间距倍数，默认为1.5（仅在图片水印的repeat模式下有效）', 'F', 'T', NULL, '/plugin/watermark/detail', 'sdk', 'all', NULL), (1320729073352179712, '时间工具', 'plugin_1320729073347985408', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/time/execute', 1, '2025-12-23 20:25:49', '00A', 1, '2026-04-17 20:30:27', '时间工具插件提供了丰富的时间处理功能，包括时间格式转换、时区时间获取和时区转换。插件支持自定义时间格式字符串，支持多种时区格式（UTC偏移量和标准时区名称），能够满足各种时间处理场景的需求。', NULL, '## 插件描述\r\n  时间工具插件提供了丰富的时间处理功能，包括时间格式转换、时区时间获取和时区转换。插件支持自定义时间格式字符串，支持多种时区格式（UTC偏移量和标准时区名称），能够满足各种时间处理场景的需求。\r\n\r\n  ## 使用场景\r\n  - **时间格式转换**：将时间从一种格式转换为另一种格式，适用于不同系统间的时间数据格式统一、日志时间格式化、报表时间显示等场景\r\n  - **时区时间获取**：获取指定时区的当前时间，适用于跨时区业务、全球服务时间显示、时区时间查询等场景\r\n  - **时区转换**：将时间从一个时区转换到另一个时区，适用于跨时区会议时间安排、全球业务时间同步、时区时间计算等场景\r\n  - **数据迁移**：在不同系统间迁移时间数据时，进行格式和时区的统一转换\r\n  - **报表生成**：在生成报表时，统一时间格式和时区\r\n\r\n  ## 参数说明\r\n  - **time**（时间字符串）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：需要转换的时间字符串，必须符合fromFormat指定的格式，默认使用当前系统时间\r\n\r\n  - **fromFormat**（原始格式）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：输入时间字符串的格式，使用Java DateTimeFormatter格式字符串，默认为yyyy-MM-dd HH:mm:ss\r\n\r\n  - **toFormat**（目标格式）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：输出时间字符串的格式，使用Java DateTimeFormatter格式字符串，默认为yyyy-MM-dd HH:mm:ss\r\n\r\n  - **timeZone**（时区标识）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：时区标识，支持UTC偏移量格式（如UTC、UTC+1、UTC+08:00）和标准时区名称（如Asia/Shanghai、America/New_York），默认使用系统当前时区\r\n\r\n  - **fromTimezone**（原始时区）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：输入时间所在的时区，支持UTC偏移量格式和标准时区名称，默认使用系统当前时区\r\n\r\n  - **toTimezone**（目标时区）：\r\n    - 类型：string\r\n    - 必填：否\r\n    - 说明：目标时区，支持UTC偏移量格式和标准时区名称，默认使用系统当前时区', 'F', 'T', NULL, '/plugin/time/detail', 'sdk', 'all', NULL), (1320729393083973632, '随机数获取', 'plugin_1320729393079779328', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/randomNumber/execute', 1, '2025-12-23 20:27:05', '00A', 1, '2026-04-17 20:29:34', '随机数获取插件提供了丰富的随机数生成功能，包括指定范围内的随机数生成和多种类型的验证码生成。插件支持自定义最小值、最大值、小数精度等参数，可生成数字验证码、字母验证码和混合验证码，满足各种业务场景的需求。', NULL, '## 插件描述\r\n  随机数获取插件提供了丰富的随机数生成功能，包括指定范围内的随机数生成和多种类型的验证码生成。插件支持自定义最小值、最大值、小数精度等参数，可生成数字验证码、字母验证码和混合验证码，满足各种业务场景的需求。\r\n\r\n  ## 使用场景\r\n  - **随机数生成**：生成指定范围内的随机数，可用于抽奖、随机分配、模拟数据生成等场景\r\n  - **数字验证码**：生成纯数字验证码，适用于短信验证码、邮箱验证码等场景\r\n  - **字母验证码**：生成纯字母验证码，支持大写、小写或混合模式，适用于需要字母验证的场景\r\n  - **混合验证码**：生成数字+字母的混合验证码，安全性更高，适用于注册、登录、密码重置等安全验证场景\r\n  - **测试数据生成**：在开发和测试过程中生成随机测试数据\r\n  - **游戏开发**：生成随机道具、随机事件等游戏元素\r\n\r\n  ## 参数说明\r\n  - **min**（最小值）：\r\n    - 类型：number\r\n    - 必填：否\r\n    - 说明：随机数的最小值，默认为0.0\r\n\r\n  - **max**（最大值）：\r\n    - 类型：number\r\n    - 必填：否\r\n    - 说明：随机数的最大值，默认为100.0\r\n\r\n  - **precision**（小数位数）：\r\n    - 类型：integer\r\n    - 必填：否\r\n    - 说明：生成随机数的小数位数，必须是大于等于0的整数，默认为0（生成整数）\r\n\r\n  - **length**（验证码长度）：\r\n    - 类型：integer\r\n    - 必填：是\r\n    - 说明：生成的验证码的字符长度，必须是大于0的正整数\r\n\r\n  - **caseType**（字母类型）：\r\n    - 类型：string\r\n    - 必填：是（在字母验证码和混合验证码功能中）\r\n    - 说明：验证码中字母的大小写类型，可选值：大写、小写、混合', 'F', 'T', NULL, '/plugin/randomNumber/detail', 'sdk', 'all', NULL), (1320729795481305088, '百度翻译', 'plugin_1320729795477110784', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/baiduTranslate/execute', 1, '2025-12-23 20:28:41', '00A', 1, '2026-04-17 20:31:23', '百度翻译插件，提供多语言翻译功能，支持自动检测源语言和多种目标语言之间的翻译', '[{\"name\":\"应用ID\",\"code\":\"appid\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"应用密钥\",\"code\":\"appkey\",\"value\":\"\",\"type\":\"header\"}]', '## 插件描述\r\n  百度翻译插件，提供多语言翻译功能，支持自动检测源语言和多种目标语言之间的翻译。\r\n\r\n  ## 使用场景\r\n  - **文档翻译**：翻译技术文档、报告等各类文本内容\r\n  - **实时翻译**：在应用中集成实时翻译功能\r\n  - **内容本地化**：将内容翻译为多种语言以适应不同地区用户\r\n  - **跨语言交流**：帮助用户理解不同语言的文本内容\r\n  - **多语言内容生成**：为国际化业务生成多语言内容\r\n\r\n  ## 参数说明\r\n  - **appId**（APP ID）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：百度翻译API的应用ID，用于身份验证和访问控制\r\n\r\n  - **appKey**（密钥）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：百度翻译API的密钥，用于身份验证和访问控制\r\n\r\n  - **text**（要翻译的文本）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：需要进行翻译的原始文本内容\r\n\r\n  - **from**（源语言）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：源语言代码，支持auto自动检测语言\r\n\r\n  - **to**（目标语言）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：目标语言代码，不支持auto，需要明确指定翻译目标语言', 'T', 'T', NULL, '/plugin/baiduTranslate/detail', 'sdk', 'all', NULL), (1320730417316233216, '提示词优化', 'plugin_1320730417312038912', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/promptOptimization/execute', 1, '2025-12-23 20:31:09', '00A', 1, '2026-04-17 20:29:39', '提示词优化插件，基于大语言模型对用户输入的提示词进行优化，提升提示词的质量和生成效果。', NULL, '## 插件描述\r\n  提示词优化插件，基于大语言模型对用户输入的提示词进行优化，提升提示词的质量和生成效果。\r\n\r\n  ## 使用场景\r\n  - **AI绘画优化**：优化AI绘画提示词，提升生成图像的质量\r\n  - **创意设计**：帮助用户优化创意设计的提示词，获得更好的生成效果\r\n  - **内容创作**：优化文生图应用中的提示词，提高生成内容的准确性\r\n  - **图像生成**：在文生图应用中提供提示词优化功能，改善生成结果\r\n\r\n  ## 参数说明\r\n  - **prompt**（提示词内容）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：用户输入的原始提示词内容，需要进行优化的文本', 'F', 'T', NULL, '/plugin/promptOptimization/detail', 'sdk', 'all', NULL), (1320731199365185537, '网页内容提取', 'plugin_1320731199365185536', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/webPageFetch/execute', 1, '2025-12-23 20:34:15', '00A', 1, '2026-04-17 20:30:40', '网页爬虫插件是一个专业的网页内容提取工具，能够从指定的网页URL地址获取并提取网页的文本内容。插件使用JSoup库进行网页解析，自动移除脚本、样式、广告等无关元素，只保留网页的核心文本内容。插件内置了完善的安全校验机制，防止SSRF（服务器端请求伪造）攻击，确保只能访问合法的外部网页资源。', NULL, '  ## 插件描述\r\n\r\n  网页爬虫插件是一个专业的网页内容提取工具，能够从指定的网页URL地址获取并提取网页的文本内容。插件使用JSoup库进行网页解析，自动移除脚本、样式、广告等无关元素，只保留网页的核心文本内容。插件内置了完善的安全校验机制，防止SSRF（服务器端请求伪造）攻击，确保只能访问合法的外部网页资源。\r\n\r\n  插件支持HTTP和HTTPS协议，具备自动重试机制（最多重试2次），能够处理网页重定向，模拟浏览器访问行为，确保能够正确获取大部分网页内容。插件会自动清理HTML标签，提取纯文本内容，方便后续的文本分析和处理。\r\n\r\n  ## 使用场景\r\n\r\n  - **网页内容抓取**：从新闻网站、博客、论坛等网页中提取文章正文内容\r\n  - **信息聚合**：批量抓取多个网页的内容，进行信息汇总和分析\r\n  - **内容分析**：提取网页文本内容后，进行关键词提取、情感分析等处理\r\n  - **数据采集**：从公开网页中采集结构化或非结构化数据\r\n  - **网页监控**：定期抓取指定网页内容，监控内容变化\r\n  - **知识库构建**：从网页中提取知识内容，用于构建知识库或训练数据\r\n\r\n  ## 参数说明\r\n\r\n  插件主要包含以下参数：\r\n  - **webPageUrl**：网页URL地址，必填参数，支持HTTP和HTTPS协议\r\n    - 格式要求：必须是完整的URL地址，以 `http://` 或 `https://` 开头\r\n    - 安全限制：禁止访问本地地址（localhost、127.0.0.1、192.168.x.x等内网IP）\r\n    - 推荐值：公开可访问的网页URL，如 `https://www.example.com/article`\r\n', 'F', 'T', NULL, '/plugin/webPageFetch/detail', 'sdk', 'all', NULL), (1320731897075073024, '高德坐标转换', 'plugin_1320731897070878720', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/gaodeGeocode/execute', 1, '2025-12-23 20:37:02', '00A', 1, '2026-04-17 20:31:18', '基于高德地图API，提供地址到坐标的转换功能。可以将中文地址、英文地址或结构化地址转换为对应的经纬度坐标。插件支持多种地址格式，包括省市区详细地址、地标名称、POI名称等，能够准确识别并返回地址对应的坐标位置。', '[{\"name\":\"key\",\"code\":\"key\",\"value\":\"\",\"type\":\"header\"}]', '## 插件描述\r\n  基于高德地图API，提供地址到坐标的转换功能。可以将中文地址、英文地址或结构化地址转换为对应的经纬度坐标。插件支持多种地址格式，包括省市区详细地址、地标名称、POI名称等，能够准确识别并返回地址对应的坐标位置。\r\n\r\n  ## 使用场景\r\n  - **地址解析和坐标定位**：将用户输入的地址文本转换为精确的经纬度坐标，用于地图定位和导航\r\n  - **地图应用开发**：在地图应用中实现地址搜索和定位功能\r\n  - **位置服务系统**：为LBS（基于位置的服务）应用提供地址解析能力\r\n  - **地址标准化处理**：将非标准格式的地址转换为标准化的坐标数据\r\n  - **地理信息系统（GIS）应用**：为GIS系统提供地址编码和坐标转换功能\r\n  - **物流配送系统**：根据收货地址获取精确坐标，优化配送路线规划\r\n\r\n  ## 参数说明\r\n  - **key**（高德API密钥）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：高德API密钥，用于API身份认证。可在高德开放平台（https://lbs.amap.com/）申请获取。申请时需要创建应用并选择Web服务API类型。\r\n\r\n  - **address**（地址）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：要查询的地址文本。支持中文地址、英文地址或结构化地址，如：\r\n      - 结构化地址：如\"北京市朝阳区建国路88号\"\r\n      - 地标名称：如\"天安门广场\"\r\n      - POI名称：如\"北京西站\"\r\n      - 简要地址：如\"北京市海淀区中关村\"', 'T', 'T', NULL, '/plugin/gaodeGeocode/detail', 'sdk', 'all', NULL), (1320732425834201088, '生成二维码', 'plugin_1320732425783869440', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/qrCodeGenerate/execute', 1, '2025-12-23 20:39:08', '00A', 1, '2026-04-17 20:29:46', '二维码生成插件支持将文本、URL、联系方式等信息编码为二维码图片。插件提供了丰富的自定义选项，包括尺寸、颜色、图片格式、错误纠正级别等参数，并可选择性地在二维码中心添加Logo图标。生成的二维码以Base64编码的data URI格式返回，可直接用于网页显示、API调用或进一步处理。', NULL, '  ## 插件描述\r\n\r\n  二维码生成插件支持将文本、URL、联系方式等信息编码为二维码图片。插件提供了丰富的自定义选项，包括尺寸、颜色、图片格式、错误纠正级别等参数，并可选择性地在二维码中心添加Logo图标。生成的二维码以Base64编码的data URI格式返回，可直接用于网页显示、API调用或进一步处理。\r\n\r\n  ## 使用场景\r\n\r\n  - **网站/应用推广**：生成包含网站链接、应用下载地址的二维码，用于线上线下推广活动\r\n  - **产品信息展示**：为产品生成包含详细信息的二维码，用户扫码即可获取产品介绍、使用说明等\r\n  - **活动营销**：生成活动报名、优惠券领取等营销活动的二维码，提升用户参与度\r\n  - **联系方式分享**：生成包含电话号码、邮箱、微信等联系方式的二维码，方便快速添加联系人\r\n  - **WiFi密码分享**：生成WiFi连接信息的二维码，用户扫码即可自动连接WiFi网络\r\n  - **支付收款**：生成支付二维码，支持支付宝、微信支付等移动支付场景\r\n  - **品牌定制二维码**：通过添加Logo和自定义颜色，生成具有品牌特色的二维码，提升品牌识别度\r\n  - **批量生成场景**：在自动化流程中批量生成二维码，如批量制作产品标签、活动物料等\r\n\r\n  ## 参数说明\r\n\r\n  - **必填参数**：content（二维码内容）是唯一必填参数，支持文本、URL、JSON等任意字符串\r\n  - **尺寸参数**：width和height用于控制二维码图片的像素大小，默认300x300，可根据使用场景调整\r\n  - **格式参数**：format支持png、jpg、jpeg三种格式，默认png，可根据存储和传输需求选择\r\n  - **错误纠正级别**：errorCorrectionLevel支持L、M、Q、H四个级别，级别越高容错能力越强但二维码越复杂，默认M适合大多数场景\r\n  - **Logo功能**：支持通过文件上传或Base64编码两种方式添加Logo，Logo会自动居中显示并添加白色背景\r\n  - **颜色定制**：foregroundColor和backgroundColor支持十六进制颜色值，可自定义二维码的前景色和背景色\r\n  - **输出格式**：返回JSON对象，包含base64字段（data URI格式），可直接用于HTML img标签或API调用\r\n', 'F', 'T', NULL, '/plugin/qrCodeGenerate/detail', 'sdk', 'all', NULL), (1320732968493252608, '读取Excel文件内容', 'plugin_1320732968489058304', 'data:image/png;base64,', 1320583828336009216, 1320647030687748096, 'tool', '1', 'local', '/plugin/excelToData/execute', 1, '2025-12-23 20:41:17', '00A', 1, '2026-04-17 20:30:07', 'Excel转数据插件，提供将Excel文件转换为结构化数据的功能，支持list和map两种数据格式，方便对Excel数据进行进一步处理和分析。', NULL, '## 插件描述\r\n  Excel转数据插件，提供将Excel文件转换为结构化数据的功能，支持list和map两种数据格式，方便对Excel数据进行进一步处理和分析。\r\n\r\n  ## 使用场景\r\n  - **数据导入**：将Excel数据导入到数据库或应用程序中\r\n  - **数据转换**：将Excel格式的数据转换为便于处理的结构化格式\r\n  - **数据清洗**：对Excel数据进行预处理和清洗操作\r\n  - **报表处理**：处理和分析Excel格式的报表数据\r\n  - **批量数据处理**：批量处理Excel文件中的数据\r\n\r\n  ## 参数说明\r\n  - **file**（Excel文件）：\r\n    - 类型：file\r\n    - 必填：是\r\n    - 说明：需要转换的Excel文件，支持xlsx和xls格式\r\n\r\n  - **dataType**（数据类型）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：指定输出数据的格式，可选值：\r\n      - list：列表格式，每行为一个列表，适用于简单的行数据处理\r\n      - map：Map格式，第一行作为表头，适用于结构化数据处理', 'F', 'T', NULL, '/plugin/excelToData/detail', 'sdk', 'all', NULL), (1320931129061015553, '股票数据', 'plugin_1320931129061015552', 'data:image/png;base64,', 1320930918439845888, 1320647076380495872, 'mcp', '1', 'streamable', '/cnstock/mcp', 1, '2025-12-24 09:48:42', '00A', 1, '2026-04-17 20:30:44', '股票数据以 MCP 协议，提供及时、准确的股票基本信息、行情、财务、技术指标等股票数据，以便大模型对股票进行分析和解读。', NULL, '服务介绍\r\n\r\n## 什么是 股票数据 MCP 服务？\r\n\r\n股票数据 MCP 为大模型提供及时、准确的股票数据，使得大模型可以依据其金融专业知识，对用户的关于股票相关的问题进行解答和分析。\r\n\r\n## 股票数据 MCP 服务的关键特性\r\n\r\n目前股票数据为大模型提供以下的数据\r\n\r\n* 基本信息：包括股票名称，所属板块等\r\n* 行情数据：当前的行情，以及相关可供参考的历史统计\r\n* 财务数据：近年的公司主要财务数据\r\n* 技术指标：若干常用技术指标\r\n\r\n这些数据，被划分成三个工具\r\n\r\n* brief: 给定股票的基本信息，行情数据\r\n* medium: 提供所有基本数据和一些财务数据\r\n* full: 提供所有中等数据和技术指标\r\n\r\n由大模型根据用户的问题需要，自行选择调用。\r\n\r\n## 股票数据 MCP 服务的使用案例\r\n\r\n### 盘面分析\r\n\r\n通过系统提词\r\n\r\n```\r\n你是一个专业的投资顾问，请根据用户的输入，推断出股票代码，然后调用相关的工具，进行走势分析。\r\n请在分析时标明当前的数据日期\r\n你应该应用你的金融学知识，着重对数据进行专业解读。\r\n```\r\n\r\n配合本 MCP，大模型可以对 “浦发银行” 进行分析和解读。\r\n\r\n```\r\n好的，我将为您分析浦发银行的股票走势。浦发银行的股票代码为 **SH600000**（上海证券交易所上市）。我将调用相关工具获取最新的数据并进行分析。\r\n\r\n# 浦发银行 (SH600000) 股票走势分析\r\n\r\n**数据日期：2025年5月6日**\r\n\r\n以下是对浦发银行 (SH600000) 的详细分析，基于提供的最新数据，结合金融学知识，从基本面、交易数据、技术指标等多个角度进行解读。\r\n\r\n---\r\n\r\n## 1. 基本面分析\r\n\r\n- **行业概念**：浦发银行属于信托概念、证金持股、跨境支付(CIPS) 和高股息精选等概念板块。这些标签表明其在金融领域具有多元化业务布局，尤其是在高股息领域，可能对追求稳定收益的投资者具有吸引力。\r\n- **市盈率 (PE)**：4.90，处于较低水平，表明股票估值相对较低，可能被市场低估，但也可能反映市场对其未来增长预期的悲观。\r\n- **市净率 (PB)**：0.33，远低于1，表明股价低于每股净资产，可能是价值投资的机会，但也可能反映资产质量或盈利能力问题。\r\n- **净资产收益率 (ROE)**：2.65%，相对较低，显示公司资本利用效率不高，盈利能力有待提升。\r\n\r\n### 财务数据趋势\r\n从过去五年的财务数据来看：\r\n- **主营收入**：2020年至2022年呈下降趋势，2023年略有回升，但2024年再次小幅下降至1707.48亿元，显示业务增长乏力。\r\n- **净利润**：2020年至2022年持续下降，2023年有所回升至367.02亿元，2024年进一步增长至452.57亿元，表明盈利能力正在逐步恢复。\r\n- **每股收益 (EPS)** 和 **每股净资产 (NAV)**：EPS 从2020年的1.88元下降至2023年的1.07元，2024年回升至1.36元；NAV 持续增长，2024年达到22.36元，显示公司资产积累能力较强。\r\n- **净资产收益率 (ROE)**：从2020年的10.46%下降至2023年的5.10%，2024年小幅回升至6.08%，反映出盈利效率仍未恢复到前期水平。\r\n\r\n**基本面总结**：浦发银行目前估值较低，具有一定的价值投资潜力，但盈利能力和业务增长面临挑战。净利润的回升是一个积极信号，但主营收入的波动和较低的ROE 表明其长期增长仍需观察。\r\n\r\n---\r\n\r\n## 2. 交易数据分析\r\n\r\n### 价格趋势\r\n- **短期 (5日)**：均价10.858元，最高11.190元，最低10.570元，累计涨跌幅+5.48%，显示短期内股价有较强的上涨动能。\r\n- **中期 (20日)**：均价10.510元，累计涨跌幅+6.58%，价格波动范围较大（最高11.190元，最低9.460元），表明中期趋势向上，但波动性较高。\r\n- **长期 (240日)**：均价9.468元，累计涨跌幅+43.21%，显示长期趋势非常强劲，股价从低点7.760元上涨至当前水平，反映市场对该股的信心逐步增强。\r\n\r\n### 成交量与换手率\r\n- **成交量**：当日成交量97.26万手，显著高于5日均量（67.21万手）和20日均量（69.60万手），表明近期市场参与度增加，资金流入明显。\r\n- **换手率**：当日换手率0.33%，5日总换手率1.14%，20日总换手率4.74%，显示短期交易活跃度较高，但长期来看换手率较低（240日均换手0.17%），投资者多以持有为主。\r\n\r\n### 振幅\r\n- **短期 (5日)**：振幅5.87%，显示短期波动较为温和。\r\n- **长期 (240日)**：振幅44.20%，表明长期内价格波动较大，投资者需关注风险。\r\n\r\n**交易数据总结**：浦发银行近期价格呈上涨趋势，尤其是短期和中期动能较强，成交量放大显示资金关注度提升。然而，长期振幅较大，投资者需警惕价格回调风险。\r\n\r\n---\r\n\r\n## 3. 技术指标分析\r\n\r\n### KDJ 指标\r\n- 最新数据 (2025-05-06)：K=86.38，D=81.30，J=96.54，处于高位，显示股价短期内处于超买状态，可能面临回调压力。\r\n- 趋势：过去30日KDJ指标整体呈上升趋势，J值多次超过100，反映市场情绪较为乐观，但需警惕超买风险。\r\n\r\n### MACD 指标\r\n- 最新数据：DIF=0.16，DEA=0.10，DIFF>DEA，且DIFF持续扩大，显示多头动能增强，短期趋势仍为看涨。\r\n- 趋势：过去30日MACD指标从负值转为正值，表明股价从弱势转为强势，目前仍处于多头排列。\r\n\r\n### RSI 指标\r\n- 最新数据：RSI(6)=77.85，RSI(12)=67.60，RSI(24)=61.28，其中RSI(6)处于超买区域（>70），短期可能有调整需求。\r\n- 趋势：RSI指标整体处于50以上，显示市场处于强势，但短期超买信号需关注。\r\n\r\n### 布林带 (BBands)\r\n- 最新数据：上轨11.26元，中轨10.86元，下轨10.47元，当前股价11.17元接近上轨，显示价格处于高位，短期可能面临阻力。\r\n- 趋势：布林带近期持续走宽，表明波动性增加，股价突破中轨后持续靠近上轨，显示多头力量占优。\r\n\r\n**技术指标总结**：多项指标显示浦发银行短期处于超买状态，KDJ和RSI均提示回调风险，但MACD和布林带仍显示多头趋势，短期内上涨动能可能延续，建议投资者关注回调后的买入机会。\r\n\r\n---\r\n\r\n## 4. 综合分析与投资建议\r\n\r\n### 优点\r\n1. **低估值**：市盈率和市净率均处于较低水平，具有一定的价值投资吸引力。\r\n2. **长期趋势向上**：240日涨跌幅高达43.21%，显示长期市场信心较强。\r\n3. **短期动能强劲**：5日和20日涨跌幅分别为5.48%和6.58%，成交量放大，资金流入明显。\r\n4. **财务改善**：净利润和每股收益在2024年有所回升，显示盈利能力逐步恢复。\r\n\r\n### 风险\r\n1. **盈利效率低**：净资产收益率较低，业务增长乏力，主营收入波动较大。\r\n2. **短期超买**：技术指标显示股价处于超买状态，短期可能面临回调压力。\r\n3. **波动性高**：长期振幅较大，投资者需关注市场波动风险。\r\n\r\n### 投资建议\r\n- **短期投资者**：当前股价处于高位，技术指标显示超买，建议观望，等待回调至布林带中轨（10.86元）附近或更低水平再考虑介入。\r\n- **中长期投资者**：考虑到低估值和长期上涨趋势，可在回调时分批建仓，关注10.50-10.80元支撑位，同时设置止损位以控制风险。\r\n- **风险控制**：建议关注后续成交量是否持续放大，若成交量萎缩且股价跌破10.47元（布林带下轨），需警惕进一步下行风险。\r\n\r\n**总结**：浦发银行目前具有一定的投资价值，但短期超买风险需警惕。投资者应结合自身风险承受能力和投资周期，合理制定操作策略。\r\n```\r\n\r\n### 数据解读\r\n\r\n用户询问 `浦发银行最近波动大吗？`，通过本MCP，模型回复\r\n\r\n```\r\n为了分析浦发银行的近期波动情况，我将推断其股票代码并调用相关工具获取数据。浦发银行的股票代码为 **SH600000**（上海证券交易所上市）。我将使用 `brief` 函数来获取基本的交易数据，以便初步判断其波动情况。如果需要更详细的分析，我会进一步调用其他工具。\r\n\r\n# 浦发银行 (SH600000) 近期波动分析\r\n\r\n**数据日期：2025年5月6日**\r\n\r\n## 1. 价格波动分析\r\n- **当日波动**：浦发银行当日价格波动幅度为 **5.57%**，价格在 **10.80元至11.19元** 之间波动，收盘价为 **11.17元**，较前一日上涨 **1.92%**。\r\n- **短期波动（5日）**：过去5日的价格波动幅度为 **5.87%**，价格区间为 **10.57元至11.19元**，均价为 **10.858元**，累计涨幅为 **5.48%**。短期内波动相对温和，但有一定的上涨动能。\r\n- **中期波动（20日）**：过去20日的价格波动幅度较大，为 **18.29%**，价格区间为 **9.46元至11.19元**，均价为 **10.51元**，累计涨幅为 **6.58%**。中期波动显示出较强的价格回升趋势。\r\n- **长期波动（240日）**：过去240日的价格波动幅度非常显著，为 **44.20%**，价格区间为 **7.76元至11.19元**，均价为 **9.468元**，累计涨幅高达 **43.21%**。长期来看，浦发银行股价呈现出较强的上涨趋势。\r\n\r\n## 2. 成交量与换手率分析\r\n- **当日成交量**：当日成交量为 **97.26万手**，显著高于5日均量（**67.21万手**）和20日均量（**69.60万手**），显示出市场参与度在当日有所提升。\r\n- **换手率**：当日换手率为 **0.33%**，高于5日均换手率（**0.23%**）和20日均换手率（**0.24%**）。虽然整体换手率不高，但短期内市场活跃度有所增加。\r\n\r\n## 3. 估值指标分析\r\n- **市盈率 (PE)**：当前为 **4.90**，处于较低水平，表明股票估值相对较低，可能存在低估空间。\r\n- **市净率 (PB)**：当前为 **0.33**，远低于1，显示市场对公司净资产的估值较低，可能是价值投资的潜在标的。\r\n- **净资产收益率 (ROE)**：当前为 **2.65%**，表明公司盈利能力一般，需关注其未来的盈利改善情况。\r\n\r\n## 4. 综合解读与投资建议\r\n从价格波动来看，浦发银行近期（尤其是过去5日和20日）股价呈现出一定的上涨趋势，但波动幅度在短期内相对可控（5日振幅5.87%），并未表现出剧烈波动。中长期来看（240日振幅44.20%），股价经历了较大的上涨，显示出较强的趋势性行情。\r\n\r\n成交量和换手率的提升表明市场对浦发银行的关注度有所增加，尤其是当日成交量的显著放大，可能预示着短期内仍有上涨动能。然而，换手率整体偏低，市场流动性一般，需警惕可能的成交量萎缩风险。\r\n\r\n从估值角度看，浦发银行的市盈率和市净率均处于较低水平，显示出一定的价值投资吸引力，但较低的净资产收益率提示其盈利能力有待提升，投资者需关注其后续财报数据及行业环境变化。\r\n\r\n**总结**：浦发银行近期波动幅度在短期内并不算大，但中长期趋势显示出较强的上涨动能。结合低估值特性，短期内可适当关注，但需警惕成交量变化及盈利能力的潜在风险。建议投资者密切关注行业政策（如高股息政策、跨境支付概念等）对股价的进一步催化作用。\r\n\r\n如果您需要更详细的财务数据或技术分析指标，可以进一步调用“medium”或“full”工具进行深入分析。\r\n```\r\n\r\n## 常见问题解答\r\n\r\nQ：使用股票MCP服务是否需要付费\r\n\r\nA：该服务目前限时免费体验，未来请关注项目主页 [https://github.com/elsejj/mcp-cn-a-stock](https://github.com/elsejj/mcp-cn-a-stock?spm=5176.28197581.d_mcp.1.cadc5a9emphSR8) 的更新。\r\n\r\nQ：联系方式\r\n\r\nA：请在 [https://github.com/elsejj/mcp-cn-a-stock/issues](https://github.com/elsejj/mcp-cn-a-stock/issues?spm=5176.28197581.d_mcp.2.cadc5a9emphSR8) 发起问题或向 cs@kanhq.com 发送邮件，谢谢。', 'F', 'T', NULL, NULL, NULL, 'all', NULL);
INSERT INTO `pt_plugin` VALUES (1320932191218171904, '智谱联网搜索', 'plugin_1320932191213977600', 'data:image/png;base64,', 1320931899248476160, 1320647076380495872, 'mcp', '1', 'sse', '/api/mcp/web_search/sse', 1, '2025-12-24 09:52:56', '00A', 1, '2026-04-17 20:31:09', '智谱网络搜索MCP服务器是专为大模型设计的搜索引擎，整合了四种搜索引擎，可以让用户灵活对比和切换。在传统搜索引擎的网页爬取和排序能力基础上，增强意图识别能力，返回更适用于大模型处理的结果（如网页标题、网址、摘要、站点名称、站点图标等），帮助AI应用实现“动态知识获取”和“精准场景适配”的能力。', '[{\"name\":\"密钥\",\"code\":\"Authorization\",\"value\":\"\",\"type\":\"query\"}]', '**简介**\r\n\r\nZhipu Web Search MCP Server是一个专给大模型用的搜索引擎，整合了4家搜索引擎供用户灵活对比切换，在传统搜索引擎网页抓取、排序的能力基础上，增强了意图识别能力，返回更适合大模型处理的结果（网页标题、网页URL、网页摘要、网站名称、网站图标等），帮助AI应用获得“动态知识获取”与“精准场景适配”的能力。\r\n\r\n**Overview**\r\n\r\n**什么是Zhipu Web Search MCP服务？**\r\n\r\nZhipu Web Search MCP Server是[智谱开放平台](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)（BigModel.cn)推出的一个专给大模型用的搜索引擎，整合了4家搜索引擎供用户灵活对比切换，在传统搜索引擎网页抓取、排序的能力基础上，增强了意图识别能力，返回更适合大模型处理的结果（网页标题、网页URL、网页摘要、网站名称、网站图标等），帮助 AI 应用获得“动态知识获取”与“精准场景适配”的能力。\r\n\r\n**如何使用Zhipu Web Search MCP？**\r\n\r\n支持运行 MCP 协议的客户端，如Cursor、Cherry Studio等中配置，在[智谱 BigModel开放平台](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)复制您的 API 密钥，并按照文档内容设置服务器命令。\r\n\r\n**Zhipu Web Search MCP服务的关键特性**\r\n\r\n**实时联网搜索：** 实时检索全网信息和网页链接。\r\n\r\n**意图增强检索：** 结合智谱自研的向量、语义匹配、时效性、内容质量度等模型，针对用户提问进行意图识别，优化提取query 搜索词。同时使用自研 semantic reranker 分析用户问题与给定搜索结果的相关度，结合时效性给出打分和排序，为用户提供准确可靠的搜索结果。\r\n\r\n**多引擎支持 :**  整合智谱自研引擎及主流搜索引擎（搜狗/夸克/Jina.ai），开发者可以按场景需求灵活调用，发挥不同搜索工具的优势。\r\n\r\n| 名称  | 介绍  |\r\n| --- | --- |\r\n| 智谱自研搜索基础版 | 提供基础搜索能力，超高性价比。 |\r\n| 智谱自研搜索 Pro版 | 支持超长正文、更全面的搜索结果，多引擎降低空结果率提高搜索效率，搜索结果召回率更高、答案更准确。 |\r\n| 搜狗搜索 | 内容全面，可以抓取腾讯生态（腾讯新闻、企鹅号）、知乎的内容；在百科、医疗垂类场景中答案权威度更高。 |\r\n| 夸克搜索 | 支持指定范围搜索，比如可指定在金融、法律行业内搜索，提高召回准确性；全正文输出，提供覆盖 95% 网页的 3000字 长正文服务，无需再次解析URL。 |\r\n| Jina AI 搜索 | 输出结果直接精炼，适合需要明确直接答案的场景；能精准解析复杂 HTML，并将其转换为干净的 Markdown 或 JSON 格式。 |\r\n\r\n结构化输出：返回适合LLM处理的数据格式（含标题/URL/摘要/网站名/图标等）\r\n\r\n**Zhipu Web Search MCP服务的使用场景**\r\n\r\n**专业垂直研究：** 进行高质量网页检索、多源信息整合，如学术研究、法律、金融行业分析报告。\r\n\r\n**商业情报雷达：** 实时数据跟踪与分析，如监控行业动态、竞争对手信息、市场趋势等。\r\n\r\n**AI 助手/聊天机器人：** 提供实时信息搜索能力，确保回答准确性和时效性。\r\n\r\n**消费决策与规划设计：** 根据最新天气、新闻、车票等信息、进行多个选项对比，寻找最优解。\r\n\r\n**人才画像与简历优化：** 对于hr，搜索对比市场上的jd招聘信息，帮助生成或优化jd；对于求职者，搜索对比简历与目标岗位JD及相关行业成功简历的模板，帮助生成/优化简历。\r\n\r\n**安装教程**\r\n\r\n支持运行 MCP 协议的客户端，如Cursor、Cherry Studio等。\r\n\r\n点击获取[智谱 BigModel 开放平台的API Key](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)。\r\n\r\n**常见问题解答**\r\n\r\nQ：如何获取API Key？\r\n\r\nA：需在[智谱BigModel开放平台](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)注册开发者账号，获取 API Key。\r\n\r\nQ：使用Zhipu Web Search MCP是否需要付费？\r\n\r\nA：您在[智谱BigModel开放平台](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)可获得免费额度。若免费额度耗尽，则需要付费使用。有任何疑问可在智谱BigModel 开放平台中咨询客服。\r\n\r\nQ：支持哪些搜索引擎？\r\n\r\nA：支持智谱自研引擎及主流搜索引擎。智谱自研引擎：search_std（基础版）、search_pro（高阶版）。第三方引擎：search_pro_sogou （搜狗）、search_pro_quark（夸克）、search_pro_jina（Jina.ai ）。\r\n\r\n**Server Config**\r\n\r\n```json\r\n{\r\n    \\\"mcpServers\\\": {\r\n        \\\"zhipu-web-search-sse\\\": {\r\n            \\\"command\\\": \\\"docker\\\",\r\n            \\\"url\\\": \\\"https://open.bigmodel.cn/api/mcp/web_search/sse?Authorization={you ak/sk}\\\"\r\n        }\r\n    }\r\n}\r\n```\r\n\r\n**Content**\r\n\r\n**安装教程**\r\n\r\n支持运行 MCP 协议的客户端，如Cursor、Cherry Studio等。\r\n\r\n点击获取[智谱 BigModel 开放平台的API Key](https://zhipuaishengchan.datasink.sensorsdata.cn/t/cE)。\r\n\r\n**在Cursor中使用**\r\n\r\nCursor 0.45.6 版本提供了MCP功能，Cursor将作为MCP服务客户端使用MCP服务，在Cursor中通过简单的配置就可以完成MCP服务的接入。\r\n\r\n操作路径：Cursor设置-\\u003e【Features】-\\u003e【MCP Servers】。\r\n\r\n**配置MCP服务器**\r\n```json\r\n{\r\n    \"mcpServers\": {\r\n    \"zhipu-web-search-sse\": {\r\n     \"url\": \"https://open.bigmodel.cn/api/mcp/web_search/sse?Authorization=YOUR API Key\"\r\n        }\r\n    }\r\n}\r\n\r\n```\r\n', 'T', 'T', NULL, NULL, NULL, 'all', NULL), (1320932577698119680, '且慢', 'plugin_1320932577693925376', 'data:image/png;base64,', 1320932491777802240, 1320647076380495872, 'mcp', '1', 'sse', '/mcp/sse', 1, '2025-12-24 09:54:28', '00A', 1, '2026-04-17 20:31:13', '盈米且慢推出国内首个兼容MCP协议的财富管理服务平台—Qieman MCP Server（简称且慢MCP）。且慢MCP提供了完整的金融数据与专业分析工具支持，让您的AI大模型能实时提供高质量、可用且数据真实准确的金融服务。助力财富管理的行业伙伴及投资人，能一同探索体验，解决自身以及客户的真实金融问题。', '[{\"name\":\"密钥\",\"code\":\"apiKey\",\"value\":\"\",\"type\":\"query\"}]', '# 且慢MCP\r\n\r\n盈米且慢推出国内首个兼容MCP协议的财富管理服务平台—Qieman MCP Server（简称且慢MCP）。且慢MCP提供了完整的金融数据与专业分析工具支持，让您的AI大模型能实时提供高质量、可用且数据真实准确的金融服务。助力财富管理的行业伙伴及投资人，能一同探索体验，解决自身以及客户的真实金融问题。\r\n\r\n## 主要特点\r\n\r\n1.  **精确的金融数据**：调用且慢MCP可获取实时准确的金融数据，可避免常见的大模型幻觉；\r\n2.  **全面的投资研究系统**：整合了金融专家的最新分析观点和汇总信息，以提高金融信息服务的质量。\r\n3.  **专业的投资顾问系统**：调用专业投顾测算工具与各类资产分析能力，构建金融与投顾服务核心优势；\r\n4.  **便捷的用户体验**：初始配置后，服务将自动更新和升级，确保能持续使用最新的金融工具服务包。\r\n\r\n## 工具列表\r\n\r\n| 功能/API名称 | 描述 |\r\n| ---- | ---- |\r\n| BatchGetFundsDetail | 批量查询多个基金的详细信息，包括名称、类型、规模、风险级别、经理、成立日期、投资范围等。 |\r\n| BatchGetFundNavHistory | 批量获取多个基金的历史净值数据，支持按不同时间维度查询。 |\r\n| GetBatchFundPerformance | 批量获取基金的业绩数据，包括业绩分析指标和阶段回报。 |\r\n| BatchGetFundsHolding | 批量获取多个基金的持仓信息，包括十大重仓股、债券持仓等。 |\r\n| BatchGetFundsHolderInfo | 批量获取基金的资产规模和持有人结构数据，包括单份数据、总份数据和持有人结构信息。 |\r\n| BatchGetFundsFeeRule | 批量获取多个基金的费用规则，包括认购费、申购费、赎回费和操作费。 |\r\n| BatchGetFundTradeRules | 批量获取基金的交易规则，包括最低/最高购买金额、预期确认日期、预期到账日期、费用规则等。 |\r\n| BatchGetFundTradeLimit | 批量获取多个基金的交易限制信息，包括基金是否可交易、最低购买金额、最低持有份额、定投起点等。 |\r\n| BatchGetFundsSplitHistory | 批量获取基金的拆分记录信息，包括拆分日期和比例。 |\r\n| BatchGetFundsDividendRecord | 批量获取基金的分红记录，包括权益登记日、红利发放日和每份红利金额。 |\r\n| GetFundAnnouncements | 查询基金公告，包括基金代码、名称、全名、公告ID、日期、来源、标题、链接和类型。支持按时间范围、公告类型和标题关键词查询。 |\r\n| SearchFunds | 基于名称、代码或其他条件搜索基金，支持按回报、规模、费用等排序。 |\r\n| GetPopularFund | 获取最近受欢迎基金的列表，了解市场焦点和投资趋势。 |\r\n| GuessFundCode | 根据基金名称匹配最接近的基金代码。 |\r\n| GetAssetAllocation | 分析基金组合的资产配置，提供资产类别分布、雷达图评分和诊断结果。 |\r\n| GetFundsCorrelation | 分析多个基金之间的相关系数，了解组合中每个基金趋势的相互影响。 |\r\n| GetFundsBackTest | 对给定的基金组合进行历史回测分析，计算关键指标并提供全面的诊断结果和评分。 |\r\n| MonteCarloSimulate | 基于给定的资产配置权重执行蒙特卡洛模拟计算，生成预期收益分布、波动率情景和各种百分位数的收益率数据。 |\r\n| AnalyzeFundRisk | 获取多个基金的风险评分和详细风险解释，计算风险评分、R平方、残差方差、标准误差等指标。 |\r\n| AnalyzePortfolioRisk | 对给定的基金组合进行风险评估分析，计算多维风险指标。 |\r\n| SearchFinancialNews | 搜索工具支持按关键词和时间范围进行筛选和分页，返回详细的新闻内容。 |\r\n| SearchManagerViewpoint | 获取基金经理对各行业的见解和市场分析，支持按行业主题、时间范围和关键词进行筛选。 |\r\n| GetFundDiagnosis | 提供全面的基金诊断分析，包括最新信息、风险和机会评估、行业持仓、资产配置、业绩等。 |\r\n| DiagnoseFundPortfolio | 提供全面的基金组合诊断分析，包括资产配置分析、基金相关性分析和回测诊断。 |\r\n| GetAssetAllocationPlan | 基于投资参数获取资产配置计划。 |\r\n| GetCompositeModel | 通过资产配置计划ID获取相应的复合模型。 |\r\n| RenderEchart | 根据提供的ECharts配置渲染图表并转换为图像，支持返回base64编码的图像内容或OSS访问URL。 |\r\n| RenderHtmlToPdf | 将HTML内容转换为PDF文档，支持自定义PDF格式和边距设置。 |\r\n| GetCurrentTime | 获取服务器的当前时间，返回格式化的日期和时间字符串。 |\r\n| GetTxnDayRange | 基于中心时间获取指定期间内的交易日列表，支持向前和向后推算指定天数。 |\r\n\r\n## 官方网站\r\n\r\n[https://qieman.com/mcp/landing](https://qieman.com/mcp/landing)\r\n\r\n## 开始使用\r\n\r\n1.  **申请开通Qieman MCP服务**： 访问且慢MCP官方网站，登录或注册且慢账户，填写表格获取您专属的API密钥。\r\n\r\n2.  **使用链接开始获取服务**： [https://stargate.yingmi.com/mcp/sse?apiKey=[您的API密钥](https://stargate.yingmi.com/mcp/sse?apiKey=%5B%E6%82%A8%E7%9A%84API%E5%AF%86%E9%92%A5)]\r\n\r\n\r\n## 用户指南\r\n\r\n[https://qieman.com/mcp/how-to-use](https://qieman.com/mcp/how-to-use)\r\n\r\n## 联系我们\r\n\r\noap@yingmi.cn', 'T', 'T', NULL, NULL, NULL, 'all', NULL), (1320933499329314816, 'EdgeOne Pages', 'plugin_1320933499325120512', 'data:image/png;base64,', 1320933424825892864, 1320647076380495872, 'mcp', '1', 'streamable', '/mcp-server', 1, '2025-12-24 09:58:07', '00A', 1, '2026-04-17 20:30:37', '零门槛生成网页，一句话即可快速生成并部署HTML页面', NULL, '服务介绍\r\n\r\n## 什么是 EdgeOne Pages MCP 服务？\r\n\r\nEdgeOne Pages Deploy MCP 是一项专用服务，能够将 HTML 内容快速部署到 [EdgeOne Pages](https://edgeone.ai/zh/products/pages) 并生成公开访问链接。这使您能够立即预览和分享 AI 生成的网页内容。简单来说：使用了EdgeOne Pages MCP Server 后，咱们只要在代码编辑器里用“人话”跟大模型说：“帮我生成一个 xxxx 的页面并帮我直接部署”，大模型就可以一键生成并部署啦！\r\n\r\n源码地址：[https://github.com/TencentEdgeOne/edgeone-pages-mcp](https://github.com/TencentEdgeOne/edgeone-pages-mcp)\r\n\r\n## License\r\n\r\n该项目遵循 MIT 开源许可条款。请参阅 [MIT](https://github.com/TencentEdgeOne/edgeone-pages-mcp/blob/main/LICENSE) 了解完整条款。\r\n\r\n## EdgeOne Pages MCP 服务的关键特性\r\n\r\n* 快速生成并部署网页，生成即时生效的公共访问链接。\r\n* 实现秒级静态页面部署并内置错误处理机制。\r\n\r\n## EdgeOne Pages MCP 服务的使用案例\r\n\r\n* 生成一个表白网页，页面中的图片使用base64或svg展示，最后部署为在线网页\r\n* 生成一个简历网页，部署它\r\n\r\n**提示词示例**\r\n\r\n```\r\n根据用户输入内容生成一个 HTML 动态网页\r\n1. 使用Bento Grid风格的视觉设计，纯黑色底配合红色#E31937颜色作为高亮\r\n2. 强调超大字体或数字突出核心要点，画面中有超大视觉元素强调重点，与小元素的比例形成反差\r\n3. 中英文混用，中文大字体粗体，英文小字作为点缀\r\n4. 简洁的勾线图形化作为数据可视化或者配图元素\r\n5. 运用高亮色自身透明度渐变制造科技感，但是不同高亮色不要互相渐变\r\n6. 模仿 apple 官网的动效，向下滚动鼠标配合动效\r\n7. 数据可以引用在线的图表组件，样式需要跟主题一致\r\n8. 使用 Framer Motion （通过CDN引入）\r\n9. 使用HTML5、TailwindCSS 3.0+（通过CDN引入）和必要的JavaScript\r\n10. 使用专业图标库如Font Awesome或Material Icons（通过CDN引入）\r\n11. 避免使用emoji作为主要图标\r\n12. 不要省略内容要点\r\n并帮我部署这个网页\r\n```\r\n\r\n## 常见问题解答\r\n\r\nQ：使用MCP服务需要提前安装什么工具？\r\n\r\nA：需要提前安装Node.js，且Node.js版本要求18+\r\n\r\nQ：使用EdgeOne Pages MCP服务生成的网页会过期吗？有效期多久？\r\n\r\nA：生成的网页长期有效。\r\n\r\nQ：使用EdgeOne Pages MCP服务生成的网页后想二次编辑，该怎么做？\r\n\r\nA：若想对生成的网页二次修改编辑，建议将代码包拖入EdgeOne Pages生成新的部署项目，后续可在项目内修改文件。', 'F', 'T', NULL, NULL, NULL, 'all', NULL), (1320935569516134400, '高德地图', 'plugin_1320935569511940096', 'data:image/png;base64,', 1320935436128878592, 1320647076380495872, 'mcp', '1', 'sse', '/sse?key=e1f0cba05b43940c80ab739ed199d164', 1, '2025-12-24 10:06:21', '00A', 1, '2026-04-17 20:25:13', '高德地图是一个支持任何MCP协议客户端的服务器，允许用户轻松利用高德地图MCP服务器获取各种基于位置的服务。', '[{\"name\":\"密钥\",\"code\":\"key\",\"value\":\"e1f0cba05b43940c80ab739ed199d164\",\"type\":\"query\"}]', '## 产品介绍\r\n\r\n为实现 LBS 服务与 LLM 更好的交互，高德地图 MCP Server 现已覆盖12大核心服务接口，提供全场景覆盖的地图服务，包括地理编码、逆地理编码、IP 定位、天气查询、骑行路径规划、步行路径规划、驾车路径规划、公交路径规划、距离测量、关键词搜索、周边搜索、详情搜索等。\r\n\r\n为进一步提高开发者接入效率与体验，高德地图开放平台为开发者提供了[通用级 SSE 协议](https://lbs.amap.com/api/mcp-server/gettingstarted) MCP 服务解决方案。\r\n\r\n## 高德地图开放平台通用级 SSE 协议 MCP 服务解决方案\r\n\r\n#### 产品架构图\r\n\r\n![](https://a.amap.com/lbs/static/img/doc/doc_1743685971070_d2b5c.png)\r\n\r\n#### 什么是 SSE？\r\n\r\nServer-Sent Events（SSE，服务器发送事件）是一种基于 HTTP 协议的技术，允许服务器向客户端单向、实时地推送数据。在 SSE 模式下，开发者可以在客户端通过创建一个 EventSource 对象与服务器建立持久连接，服务器则通过该连接持续发送数据流，而无需客户端反复发送请求。\r\n\r\n#### 产品特点\r\n\r\n* 使用简单：适用普通用户基于MCP（SSE）方式，不必部署本地服务，简单通过 URL 地址配置即可使用。\r\n\r\n* 自动升级：我们会持续进行迭代更新，无须用户自己任何额外操作使用。\r\n\r\n* 更易于大模型理解：我们对原始的JSON结果进行了语义化的转换，更易于大模型理解内容。\r\n\r\n* 零运维成本：采用全托管云服务架构，用户无需关心服务器维护、资源扩容等底层运维问题。\r\n\r\n* 协议兼容：支持SSE长连接，适配不同业务场景的技术需求。\r\n\r\n\r\n前往 [快速接入](https://lbs.amap.com/api/mcp-server/gettingstarted) 文档，了解如何接入 MCP Server SSE 服务\r\n\r\n## 能力介绍\r\n\r\n#### 地理编码\r\n\r\n将详细的结构化地址转换为经纬度坐标。\r\n\r\n| <br><br>输入<br><br> | <br><br>address (位置信息)，city (城市信息，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>location (位置经纬度)<br><br> |\r\n\r\n#### 逆地理编码\r\n\r\n将一个高德经纬度坐标转换为行政区划地址信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>location (位置经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>addressComponent (位置信息，包括省市区等信息)<br><br> |\r\n\r\n#### IP 定位\r\n\r\nIP 定位根据用户输入的 IP 地址，定位 IP 的所在位置。\r\n\r\n| <br><br>输入<br><br> | <br><br>IP<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>province (省)，city (城市)，adcode (城市编码)<br><br> |\r\n\r\n#### 天气查询\r\n\r\n根据城市名称或者标准adcode查询指定城市的天气。\r\n\r\n| <br><br>输入<br><br> | <br><br>city (城市名称或城市adcode)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>forecasts (预报天气)<br><br> |\r\n\r\n#### 骑行路径规划\r\n\r\n用于规划骑行通勤方案，规划时会考虑天桥、单行线、封路等情况。最大支持 500km 的骑行路线规划。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>distance (规划距离)，duration (规划时间)，steps (规划步骤信息)<br><br> |\r\n\r\n#### 步行路径规划\r\n\r\n可以根据输入起点终点经纬度坐标，规划100km 以内的步行通勤方案，并且返回通勤方案的数据。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，paths (规划具体信息)<br><br> |\r\n\r\n#### 驾车路径规划\r\n\r\n根据用户起终点经纬度坐标规划以小客车、轿车通勤出行的方案，并且返回通勤方案的数据。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，paths (规划具体信息)<br><br> |\r\n\r\n#### 公交路径规划\r\n\r\n根据用户起终点经纬度坐标规划综合各类公共（火车、公交、地铁）交通方式的通勤方案，并且返回通勤方案的数据，跨城场景下必须传起点城市与终点城市。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)，city (起点城市)，cityd (终点城市)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，distance (规划距离)，transits (规划具体信息)<br><br> |\r\n\r\n#### 距离测量\r\n\r\n测量两个经纬度坐标之间的距离。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin_id (起点信息)，dest_id (终点信息)，distance (规划距离)，duration (时间)<br><br> |\r\n\r\n#### 关键词搜索\r\n\r\n根据用户传入关键词，搜索出相关的POI地点信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>keywords (搜索关键词)，city (查询城市，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>suggestion (搜索建议)，pois (地点信息列表)<br><br> |\r\n\r\n#### 周边搜索\r\n\r\n根据用户传入关键词以及坐标location，搜索出radius半径范围的POI地点信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>keywords (搜索关键词)，location (中心点经度纬度)，radius (搜索半径，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>pois (地点信息列表)<br><br> |\r\n\r\n#### 详情搜索\r\n\r\n查询关键词搜或者周边搜获取到的POI ID的详细信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>id (关键词搜或周边搜获取的poiid)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>地点详情信息<br><br>location (地点经纬度)，address (地址)，business_area (商圈)，city(城市)，type (地点类型) 等<br><br> |', 'T', NULL, NULL, NULL, NULL, 'all', NULL), (1320950455612735488, '生成ECharts图表', 'plugin_1320950455595958272', 'data:image/jpeg;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/echartsGenerator/execute', 1, '2025-12-24 11:05:30', '00A', 1, '2026-04-17 20:30:33', '根据用户数据和问题描述生成ECharts 5的option配置', NULL, '## 插件描述\r\n  ECharts图表生成插件，基于大语言模型根据用户提供的数据和问题描述自动生成ECharts 5的option配置，帮助用户快速创建图表。\r\n\r\n  ## 使用场景\r\n  - **数据可视化**：将数据快速转换为可视化图表\r\n  - **报表生成**：在报表中自动生成图表配置\r\n  - **数据分析**：根据分析需求自动生成合适的图表类型\r\n  - **图表配置生成**：为前端开发提供ECharts配置代码\r\n  - **快速原型**：快速生成图表原型供进一步调整\r\n\r\n  ## 参数说明\r\n  - **context**（上下文信息）：\r\n    - 类型：string\r\n    - 必填：是\r\n    - 说明：包含用户问题描述的上下文信息，用于确定图表类型和样式需求\r\n\r\n  - **data**（数据）：\r\n    - 类型：array\r\n    - 必填：是\r\n    - 说明：用于生成图表的数据，数组格式\r\n\r\n  - **options**（格式要求对象）：\r\n    - 类型：object\r\n    - 必填：否\r\n    - 说明：可选的格式要求对象，用于指定图表的特定配置要求\r\n', 'F', 'T', NULL, '/plugin/echartsGenerator/detail', 'sdk', 'all', NULL), (1321438288541253632, '根据地址保存文件', 'plugin_1321438288146989056', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/saveFileByUrl/execute', 1, '2025-12-25 19:23:59', '00A', 1, '2026-04-17 20:30:48', '通过免鉴权的 URL 下载内容，再通过指定服务上传对应的文件系统。', NULL, '# 根据地址保存文件\r\n\r\n## 插件概述\r\n根据地址保存文件插件提供通过URL下载内容并上传到指定文件系统的功能，支持各种类型的文件下载和存储。\r\n\r\n## 适用场景\r\n- **文件迁移**：将远程文件迁移到本地文件系统\r\n- **内容抓取**：从网络获取文件并存储到指定系统\r\n- **资源备份**：下载网络资源并保存到安全位置\r\n- **自动化处理**：在自动化流程中下载并存储文件\r\n\r\n## 使用指南\r\n### 前置条件\r\n- URL必须是免鉴权的，可以公开访问\r\n- 需要配置目标文件系统的上传接口地址和认证信息\r\n\r\n### 参数说明\r\n- **url**：需要下载的文件URL地址，必须是完整的URL格式', 'F', 'T', NULL, NULL, 'sdk', 'all', NULL), (1322756020012986368, '语音转文本', 'plugin_1322756019169931264', 'data:image/png;base64,', 1320583828336009216, 1320647200913575936, 'tool', '1', 'local', '/plugin/asr/execute', 1, '2025-12-29 10:40:10', '00A', 1, '2026-04-17 20:25:22', '语音识别，支持将多种格式的语音文件转换为文本内容。', NULL, '## 插件描述\r\n\r\n  语音识别插件支持将多种格式的语音文件转换为文本内容。插件采用先进的语音识别技术，能够准确识别中文、英文及混合语音内容，并支持多种音频格式输入。识别结果以结构化JSON格式返回，便于后续处理和使用。\r\n\r\n  ## 使用场景\r\n\r\n  - **语音消息转换**：将微信、QQ等应用中的语音消息转换为文本，方便查看和搜索\r\n  - **会议记录**：将会议录音转换为文字记录，提高会议效率和信息整理能力\r\n  - **语音笔记**：将口述内容快速转换为文本笔记，提升记录效率\r\n  - **采访整理**：将采访录音快速转换为文字稿，减少人工整理时间\r\n  - **语音输入辅助**：为听障人士或特定场景提供语音转文字辅助功能\r\n  - **内容审核**：对语音内容进行文本化处理，便于内容审核和分析\r\n  - **字幕生成**：为视频内容生成文字字幕，提升内容可访问性\r\n  - **语音搜索**：将语音查询转换为文本，用于搜索引擎或应用内搜索', 'F', 'T', NULL, '/plugin/asr/detail', 'sdk', 'all', NULL), (1322759177573117952, '文本转语音', 'plugin_1322759177564729344', 'data:image/png;base64,', 1320583828336009216, 1320647200913575936, 'tool', '1', 'local', '/plugin/tts/execute', 1, '2025-12-29 10:52:43', '00A', 1, '2026-04-17 20:32:00', '文本转语音插件支持将文本内容转换为高质量的音频文件', NULL, '## 插件描述\r\n\r\n  文本转语音插件支持将文本内容转换为高质量的音频文件。插件提供多种音色选择，包括男声、女声以及豆包AI语音合成服务，支持多种音频格式输出。插件采用先进的语音合成技术，能够生成自然流畅的语音内容。\r\n\r\n  ## 使用场景\r\n\r\n  - **有声内容制作**：将文章、新闻、小说等内容转换为音频，制作有声读物\r\n  - **语音助手**：为智能设备、应用程序提供语音反馈和交互功能\r\n  - **无障碍服务**：为视障人士提供文本内容的语音朗读服务\r\n  - **教育应用**：将教材、课件内容转换为语音，辅助语言学习\r\n  - **语音通知**：生成语音通知、提醒等，提升用户体验\r\n  - **内容播报**：自动将文本内容转换为语音进行播报\r\n  - **语音导航**：为地图导航、路径指引等提供语音播报功能\r\n  - **自动化播报**：在无人值守场景下自动播报预设文本内容', 'F', 'T', NULL, '/plugin/tts/detail', 'sdk', 'all', NULL), (1322759577294483456, '通过链接提取视频', 'plugin_1322759577290289152', 'data:image/png;base64,', 1320583828336009216, 1320647200913575936, 'tool', '1', 'local', '/plugin/videoDownloadPlugin/execute', 1, '2025-12-29 10:54:18', '00A', 1, '2026-04-17 20:31:00', '视频下载插件支持从抖音平台下载视频内容', NULL, '## 功能描述\r\n\r\n\r\n  视频下载插件支持从抖下载视频内容。插件能够提取视频的原始地址，获取视频内容、封面和标题信息，并支持将视频文件上传到指定的文件系统。\r\n\r\n\r\n  ## 使用场景\r\n\r\n\r\n  - **视频内容保存**：将喜欢的视频内容下载保存，便于离线观看或二次创作\r\n  - **素材收集**：为创作、剪辑等用途收集视频素材\r\n  - **内容分析**：下载视频后进行内容分析、数据挖掘等工作\r\n  - **视频转码**：下载原始视频后进行转码处理，适配不同设备或平台\r\n  - **备份保存**：将重要视频内容备份到本地或指定存储系统\r\n  - **批量下载**：批量下载视频内容，提高工作效率\r\n', 'F', 'T', NULL, '/plugin/videoDownloadPlugin/detail', 'sdk', 'all', NULL), (1322760233233297408, '通过图片或文字生成视频', 'plugin_1322760233229103104', 'data:image/png;base64,', 1320583828336009216, 1320647200913575936, 'tool', '1', 'local', '/plugin/videoGenerate/execute', 1, '2025-12-29 10:56:55', '00A', 1, '2026-04-17 20:30:53', '视频生成插件支持通过AI技术生成视频内容，提供文本到视频（文生视频）和图片到视频（图生视频）两种生成方式。', '[{\"name\":\"API密钥\",\"code\":\"apiKey\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"图生视频大模型编码\",\"code\":\"imageModelCode\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"文视频生成大模型编码\",\"code\":\"textModelCode\",\"value\":\"\",\"type\":\"header\"}]', '# 插件描述\r\n\r\n  视频生成插件支持通过AI技术生成视频内容，提供文本到视频（文生视频）和图片到视频（图生视频）两种生成方式。插件基于豆包大模型，能够根据用户提供的文本描述或图片内容生成高质量的视频。支持多种视频参数自定义，包括时长、分辨率和宽高比等。\r\n\r\n  ## 使用场景\r\n\r\n  - **内容创作**：根据文本描述快速生成视频内容，用于社交媒体、营销推广等\r\n  - **视频制作**：将静态图片转换为动态视频，丰富视觉表现\r\n  - **广告制作**：快速生成广告视频素材，提升制作效率\r\n  - **教育内容**：将教学内容通过AI视频生成，制作生动的教育视频\r\n  - **产品展示**：根据产品描述生成展示视频，提升用户体验\r\n  - **创意实验**：探索AI视频生成技术，进行创意内容实验\r\n  - **批量视频生成**：大规模生成视频内容，满足平台内容需求\r\n  - **视频预览**：快速生成视频原型，用于概念验证或预览', 'F', 'T', NULL, '/plugin/videoGenerate/detail', 'sdk', 'all', NULL), (1322762371296538624, '视频解析', 'plugin_1322762371225235456', 'data:image/png;base64,', 1320583828336009216, 1320647200913575936, 'tool', '1', 'local', '/plugin/videoParsePlugin/execute', 1, '2025-12-29 11:05:25', '00A', 1, '2026-04-17 20:30:56', '视频解析插件提供提取视频音频和音频格式转换析两大核心功能', NULL, '## 功能描述\r\n\r\n  视频解析插件提供提取视频音频和音频格式两大核心功能。插件能够将视频中的音频分离出来。适用于内容提取、字幕生成、语音识别等多种应用场景。\r\n\r\n  ## 使用场景\r\n\r\n  - **音频提取**：从视频中提取音频内容，用于制作音频版本的内容\r\n  - **字幕生成**：基于语音识别结果生成视频字幕，提升视频可访问性\r\n  - **内容分析**：分析视频内容，提取关键信息和文本内容\r\n  - **会议记录**：将会议视频转换为文字记录，便于整理和回顾\r\n  - **教育内容**：将教学视频内容转换为文字，便于学习和复习\r\n  - **内容审核**：提取视频中的语音和文字内容，进行内容审核\r\n  - **视频摘要**：基于解析结果生成视频内容摘要\r\n', 'F', 'T', NULL, '/plugin/videoParsePlugin/detail', 'sdk', 'all', NULL), (1322763538617479168, '票据识别', 'plugin_1322763538592313344', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/voucherIdentify/execute', 1, '2025-12-29 11:10:03', '00A', 1, '2026-04-17 20:31:04', '票据识别插件提供专业的票据信息提取功能，支持增值税发票和支付凭证的智能识别。', NULL, ' ## 插件描述\r\n\r\n  票据识别插件提供专业的票据信息提取功能，支持增值税发票和支付凭证的智能识别。插件采用先进的OCR技术和AI模型，能够准确识别票据中的关键信息，包括发票号码、金额、日期、买卖双方信息等，以及支付凭证中的收款方、金额、支付时间等信息。适用于财务自动化、报销流程、账务处理等场景。\r\n\r\n  ## 使用场景\r\n\r\n  - **财务自动化**：自动识别发票和支付凭证信息，减少人工录入工作\r\n  - **报销流程**：快速提取报销单据信息，提升报销处理效率\r\n  - **账务处理**：自动提取票据信息用于账务记录和分类\r\n  - **审计支持**：快速提取和验证票据信息，支持审计工作\r\n  - **税务管理**：自动识别发票信息，辅助税务申报和管理\r\n  - **费用管控**：自动提取费用凭证信息，实现费用管控自动化\r\n  - **数据录入**：减少手动录入，提高数据准确性\r\n  - **合规检查**：自动验证票据信息的完整性和准确性', 'F', 'T', NULL, '/plugin/voucherIdentify/detail', 'sdk', 'all', NULL), (1323220878486790144, '根据地址解析内容', 'plugin_1323220878251909120', 'data:image/png;base64,', 1320583828336009216, 1320647076380495872, 'tool', '1', 'local', '/plugin/parseFileByUrl/execute', 1, '2025-12-30 17:27:21', '00A', 1, '2026-04-17 20:31:32', '根据地址解析内容是一个文件内容解析插件，能够通过 URL 地址下载文件，并使用 OCR 技术提取其中的文字内容。', NULL, '## 概述\r\n\r\n根据地址解析内容是一个文件内容解析插件，能够通过 URL 地址下载文件，并使用 OCR 技术提取其中的文字内容。该插件支持多种文件格式，包括图片、文档，适用于各种文本提取场景。\r\n## 使用场景\r\n\r\n- 从网络图片中提取文字\r\n- 解析在线文档内容\r\n- 从视频中提取字幕或文本信息\r\n- 自动化文档处理流程\r\n- 内容审核和分析\r\n## 注意事项\r\n\r\n- 确保提供的 URL 可以公开访问\r\n- 支持的文件类型取决于 OCR 引擎能力\r\n- 大文件处理可能需要更长时间', 'F', 'T', NULL, '/plugin/parseFileByUrl/detail', 'sdk', 'all', NULL), (1323223587927482368, '飞书', 'plugin_1323223587923288064', 'data:image/png;base64,', 1320583828336009216, 1320647133439807488, 'tool', '1', 'local', '/plugin/lark/execute', 1, '2025-12-30 17:38:07', '00A', 1, '2026-04-17 20:31:36', '飞书插件是一个功能强大的集成工具，该插件支持多维表格操作、知识库文档搜索等功能，适用于数据管理和内容检索场景。', '[{\"name\":\"应用ID\",\"code\":\"appid\",\"value\":\"\",\"type\":\"header\"},{\"name\":\"应用密钥\",\"code\":\"appsecret\",\"value\":\"\",\"type\":\"header\"}]', '## 插件描述\r\n飞书插件是一个功能强大的集成工具，允许用户通过API与飞书平台进行交互。该插件支持多维表格操作、知识库文档搜索等功能，适用于数据管理和内容检索场景。\r\n\r\n## 功能特性\r\n\r\n### 多维表格功能\r\n- **创建多维表格**: 通过API创建新的多维表格应用\r\n- **管理数据表**: 创建、删除数据表，以及列出表格信息\r\n- **记录管理**: 新增、更新、删除和搜索表格记录\r\n- **字段管理**: 新增、更新、删除表格字段，以及查看字段列表\r\n\r\n### 知识库功能\r\n- **文档搜索**: 在飞书知识库中搜索相关文档\r\n- **文档信息获取**: 批量获取文档元信息和访问链接\r\n\r\n## 使用场景\r\n- 自动化数据录入和更新\r\n- 企业数据管理\r\n- 知识库内容检索\r\n- 业务流程自动化\r\n- 数据同步和集成\r\n\r\n## 配置要求\r\n- **appId**: 飞书应用ID\r\n- **appSecret**: 飞书应用密钥\r\n\r\n## 安全说明\r\n- 插件会自动管理访问令牌，确保API调用的安全性\r\n- 令牌自动刷新机制，有效期内无需重新配置\r\n- 支持从URL自动解析appToken和tableId\r\n\r\n## 注意事项\r\n- 需要预先在飞书开发者平台创建应用并获取凭证\r\n- 操作权限取决于飞书应用的授权范围\r\n- URL必须完整且可访问\r\n- 使用请在控制台一键开通以下权限\r\n```json\r\n{\r\n  \"scopes\": {\r\n    \"tenant\": [\r\n      \"im:message:send_as_bot\",\r\n      \"docx:document:readonly\"\r\n    ],\r\n    \"user\": [\r\n      \"docx:document:readonly\"\r\n    ]\r\n  }\r\n}\r\n```\r\n', 'T', 'T', NULL, '/plugin/lark/detail', 'sdk', 'all', NULL), (1325637626807640064, '图片转 Base64', 'plugin_1325637626799251456', 'data:image/png;base64,', 1320583828336009216, 1320646951717392384, 'tool', '1', 'local', '/plugin/imageToBase64/execute', 1, '2026-01-06 09:30:39', '00A', 1, '2026-04-17 20:31:40', '将图片转换为 Base64 编码的 data URL 格式', NULL, '## 插件描述\r\n\r\n图片转 Base64是一个用于将图片转换为 Base64 编码的插件。该插件能够接收上传的图片文件，并将其转换为 Base64 编码的 data URL 格式（如 `data:image;base64,xxx`）。这种格式可以直接嵌入到网页、文档或其他需要内联图片的场景中。\r\n\r\n## 插件功能\r\n\r\n- 将图片文件转换为 Base64 编码格式\r\n- 支持通过文件上传方式接收图片\r\n- 输出标准的 data URL 格式字符串\r\n\r\n## 插件使用场景\r\n\r\n1. **网页开发**：将小图片直接嵌入到 HTML 或 CSS 中，减少 HTTP 请求次数，提高页面加载速度\r\n2. **文档生成**：在生成 PDF 或其他格式文档时，将图片以 Base64 格式嵌入，确保文档的完整性\r\n3. **API 数据传输**：在需要将图片数据与其他文本数据一起传输的场景中，避免处理二进制数据的复杂性\r\n4. **邮件模板**：在 HTML 邮件中内联图片，避免外部资源加载问题\r\n5. **移动应用开发**：在某些需要将图片作为字符串处理的移动应用开发场景中使用\r\n6. **静态资源优化**：将小图标等图片资源转换为 Base64 格式，减少网络请求\r\n', 'F', 'T', NULL, '/plugin/imageToBase64/detail', 'sdk', 'all', NULL), (1325667102308360193, '文件内容读取', 'plugin_1325667102308360192', 'data:image/png;base64,', 1320583828336009216, 1320647030687748096, 'tool', '1', 'local', '/plugin/fileRead/execute', 1, '2026-01-06 11:27:46', '00A', 1, '2026-04-17 20:31:44', '读取文件内容，支持文档、音视频、图片内容的读取', NULL, '## 插件描述\r\n\r\nfileRead 是一个用于读取文件内容的插件。该插件支持多种文件类型的读取，包括文档、图片、音视频文件等。通过文件上传方式接收文件，并能够提取和返回文件的内容，为后续处理或分析提供数据支持。\r\n\r\n## 插件功能\r\n\r\n- 读取多种类型文件的内容\r\n- 支持文档、图片、音视频文件的读取\r\n- 可选择性处理文档中的图片内容\r\n- 通过文件上传方式接收文件\r\n\r\n## 插件使用场景\r\n\r\n1. **文档处理**：从各种文档格式（如 Word、PDF、TXT 等）中提取文本内容进行分析或处理\r\n2. **内容审核**：读取上传文件的内容，用于内容合规性检查或审核\r\n3. **数据提取**：从文档中提取特定信息或数据，用于后续处理或分析\r\n4. **文件预览**：在不打开原始文件的情况下预览文件内容\r\n7. **文档转换**：将文档内容转换为其他格式或结构化数据\r\n8. **图片内容分析**：当启用图片处理功能时，可以提取文档中的图片内容进行进一步分析\r\n', 'F', 'T', NULL, '/plugin/fileRead/detail', 'sdk', 'all', NULL), (1331191986060877824, '高德地图MCP', 'plugin_1331191986056683520', 'data:image/png;base64,', 1320935436128878592, 1320646951717392384, 'mcp', '1', 'streamable', '/mcp', 1, '2026-01-21 17:21:41', '00A', 1, '2026-04-17 20:25:17', '高德地图是一个支持任何MCP协议客户端的服务器，允许用户轻松利用高德地图MCP服务器获取各种基于位置的服务。', '[{\"name\":\"密钥\",\"code\":\"key\",\"value\":\"\",\"type\":\"query\"}]', '## 产品介绍\r\n\r\n为实现 LBS 服务与 LLM 更好的交互，高德地图 MCP Server 现已覆盖12大核心服务接口，提供全场景覆盖的地图服务，包括地理编码、逆地理编码、IP 定位、天气查询、骑行路径规划、步行路径规划、驾车路径规划、公交路径规划、距离测量、关键词搜索、周边搜索、详情搜索等。\r\n\r\n为进一步提高开发者接入效率与体验，高德地图开放平台为开发者提供了[通用级 SSE 协议](https://lbs.amap.com/api/mcp-server/gettingstarted) MCP 服务解决方案。\r\n\r\n## 高德地图开放平台通用级 SSE 协议 MCP 服务解决方案\r\n\r\n#### 产品架构图\r\n\r\n![](https://a.amap.com/lbs/static/img/doc/doc_1743685971070_d2b5c.png)\r\n\r\n#### 什么是 SSE？\r\n\r\nServer-Sent Events（SSE，服务器发送事件）是一种基于 HTTP 协议的技术，允许服务器向客户端单向、实时地推送数据。在 SSE 模式下，开发者可以在客户端通过创建一个 EventSource 对象与服务器建立持久连接，服务器则通过该连接持续发送数据流，而无需客户端反复发送请求。\r\n\r\n#### 产品特点\r\n\r\n* 使用简单：适用普通用户基于MCP（SSE）方式，不必部署本地服务，简单通过 URL 地址配置即可使用。\r\n\r\n* 自动升级：我们会持续进行迭代更新，无须用户自己任何额外操作使用。\r\n\r\n* 更易于大模型理解：我们对原始的JSON结果进行了语义化的转换，更易于大模型理解内容。\r\n\r\n* 零运维成本：采用全托管云服务架构，用户无需关心服务器维护、资源扩容等底层运维问题。\r\n\r\n* 协议兼容：支持SSE长连接，适配不同业务场景的技术需求。\r\n\r\n\r\n前往 [快速接入](https://lbs.amap.com/api/mcp-server/gettingstarted) 文档，了解如何接入 MCP Server SSE 服务\r\n\r\n## 能力介绍\r\n\r\n#### 地理编码\r\n\r\n将详细的结构化地址转换为经纬度坐标。\r\n\r\n| <br><br>输入<br><br> | <br><br>address (位置信息)，city (城市信息，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>location (位置经纬度)<br><br> |\r\n\r\n#### 逆地理编码\r\n\r\n将一个高德经纬度坐标转换为行政区划地址信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>location (位置经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>addressComponent (位置信息，包括省市区等信息)<br><br> |\r\n\r\n#### IP 定位\r\n\r\nIP 定位根据用户输入的 IP 地址，定位 IP 的所在位置。\r\n\r\n| <br><br>输入<br><br> | <br><br>IP<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>province (省)，city (城市)，adcode (城市编码)<br><br> |\r\n\r\n#### 天气查询\r\n\r\n根据城市名称或者标准adcode查询指定城市的天气。\r\n\r\n| <br><br>输入<br><br> | <br><br>city (城市名称或城市adcode)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>forecasts (预报天气)<br><br> |\r\n\r\n#### 骑行路径规划\r\n\r\n用于规划骑行通勤方案，规划时会考虑天桥、单行线、封路等情况。最大支持 500km 的骑行路线规划。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>distance (规划距离)，duration (规划时间)，steps (规划步骤信息)<br><br> |\r\n\r\n#### 步行路径规划\r\n\r\n可以根据输入起点终点经纬度坐标，规划100km 以内的步行通勤方案，并且返回通勤方案的数据。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，paths (规划具体信息)<br><br> |\r\n\r\n#### 驾车路径规划\r\n\r\n根据用户起终点经纬度坐标规划以小客车、轿车通勤出行的方案，并且返回通勤方案的数据。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，paths (规划具体信息)<br><br> |\r\n\r\n#### 公交路径规划\r\n\r\n根据用户起终点经纬度坐标规划综合各类公共（火车、公交、地铁）交通方式的通勤方案，并且返回通勤方案的数据，跨城场景下必须传起点城市与终点城市。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)，city (起点城市)，cityd (终点城市)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin (起点信息)，destination (终点信息)，distance (规划距离)，transits (规划具体信息)<br><br> |\r\n\r\n#### 距离测量\r\n\r\n测量两个经纬度坐标之间的距离。\r\n\r\n| <br><br>输入<br><br> | <br><br>origin (起点经纬度)，destination (终点经纬度)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>origin_id (起点信息)，dest_id (终点信息)，distance (规划距离)，duration (时间)<br><br> |\r\n\r\n#### 关键词搜索\r\n\r\n根据用户传入关键词，搜索出相关的POI地点信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>keywords (搜索关键词)，city (查询城市，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>suggestion (搜索建议)，pois (地点信息列表)<br><br> |\r\n\r\n#### 周边搜索\r\n\r\n根据用户传入关键词以及坐标location，搜索出radius半径范围的POI地点信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>keywords (搜索关键词)，location (中心点经度纬度)，radius (搜索半径，非必须)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>pois (地点信息列表)<br><br> |\r\n\r\n#### 详情搜索\r\n\r\n查询关键词搜或者周边搜获取到的POI ID的详细信息。\r\n\r\n| <br><br>输入<br><br> | <br><br>id (关键词搜或周边搜获取的poiid)<br><br> |\r\n| ---- | ---- |\r\n| <br><br>输出<br><br> | <br><br>地点详情信息<br><br>location (地点经纬度)，address (地址)，business_area (商圈)，city(城市)，type (地点类型) 等<br><br> |', 'T', NULL, NULL, NULL, NULL, 'all', NULL), (1332245705145802752, '测试MCP插件', 'plugin_1332245705141608448', 'data:image/png;base64,', 1320935436128878592, 1320646951717392384, 'mcp', '1', 'streamable', '/weather/sse', 1, '2026-01-24 15:08:48', '00A', 1, '2026-04-24 15:27:47', NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, NULL, NULL), (1335443884020453377, 'PDF文档转换', 'plugin_1335443884020453376', 'data:image/png;base64,', 1320583828336009216, 1320647030687748096, 'tool', '1', 'local', '/plugin/libreOffice/execute', 1, '2026-02-02 10:57:18', '00A', 1, '2026-04-17 20:17:49', '专业的文档格式转换工具，支持多种常见办公文档和图片格式转换为高质量 PDF 文件。', NULL, '## 功能描述\r\n  专业的文档格式转换工具，支持多种常见办公文档和图片格式转换为高质量 PDF 文件。\r\n\r\n  ### 支持的转换类型\r\n  - **Office 文档转 PDF**：Word (.doc/.docx)、Excel (.xls/.xlsx)、PowerPoint (.ppt/.pptx)\r\n  - **图片转 PDF**：JPG、PNG、BMP等常见图片格式\r\n\r\n  ## 使用场景\r\n  - 文档归档：将办公文档统一转换为 PDF 格式便于长期保存\r\n  - 文件分享：生成跨平台通用的 PDF 文件，避免格式兼容问题\r\n  - 报表输出：将 Excel 数据表格转换为打印友好的 PDF 报告\r\n  - 图片合成：将多张图片转换为 PDF 文档便于整理和传输\r\n  - 在线预览：为 Web 应用提供文档预览能力', 'F', NULL, NULL, '/plugin/libreOffice/detail', 'sdk', 'all', NULL);
INSERT INTO `pt_plugin` VALUES (1351014817367904256, '天气查询MCP', 'plugin_1351014817355321344', 'data:image/png;base64,', 1351014661587259392, 1320646951717392384, 'mcp', '1', 'sse', '/weather/sse', 1, '2026-03-17 10:10:33', '00A', 1, '2026-04-17 20:27:00', NULL, '[{\"name\":\"query\",\"code\":\"query\",\"value\":\"11\",\"remark\":\"\",\"type\":\"query\"}]', NULL, 'F', NULL, NULL, NULL, NULL, 'all', NULL), (1351026310842994689, '天气111', 'plugin_1351026310842994688', 'data:image/png;base64,', 1351014661587259392, 1320646951717392384, 'mcp', '0', 'streamable', '/mcp-servers/tianqi-demo', 1, '2026-03-17 10:56:13', '00X', 1, '2026-03-17 11:39:21', '1', NULL, NULL, 'F', NULL, NULL, NULL, NULL, NULL, NULL), (1351043731637194753, '12306票务查询', 'plugin_1351043731637194752', 'data:image/png;base64,', 1351043634388062208, 1320646951717392384, 'mcp', '1', 'streamable', '/a4ae55bd1f294c/mcp', 1, '2026-03-17 12:05:26', '00A', 1, '2026-04-13 16:18:08', NULL, NULL, NULL, 'F', NULL, NULL, NULL, NULL, 'all', NULL), (1353332691877023744, 'sad ', 'plugin_1353332691776360448', 'data:image/png;base64,', 1351014661587259392, 1320646951717392384, 'mcp', '0', 'streamable', 'asdasdadssssssssssssss2手动！@#', 1, '2026-03-23 19:40:57', '00X', 1, '2026-04-08 13:41:32', NULL, '[{\"name\":\"器未2 \",\"code\":\"啊实打实的\",\"value\":\"啊实打实！@#\",\"remark\":\"\",\"type\":\"header\"}]', NULL, 'F', NULL, NULL, NULL, NULL, NULL, NULL), (1355764144531361792, 'FunAudioLLM/CosyVoic', 'plugin_1355764144522973184', 'data:image/png;base64,', 1355762953512603648, 1320646951717392384, 'tool', '0', 'remote', '/v1/audio/speech', 1, '2026-03-30 12:42:40', '00X', 1, '2026-03-30 15:13:32', NULL, '[{\"name\":\"Authorization\",\"code\":\"Authorization\",\"value\":\"Bearer sk-htgqnsguubrzkamnkujdlfotueuikqblfquzkhleqvqjkgan\",\"remark\":\"\",\"type\":\"header\"}]', NULL, 'F', NULL, NULL, NULL, 'none', NULL, '[{\"name\":\"model\",\"code\":\"model\",\"value\":\"FunAudioLLM/CosyVoice2-0.5B:alex\",\"remark\":\"\",\"type\":\"body\"},